function extractMetadataVarsFallback(hostBridge?: HostBridge): Record<string, unknown> {
    const raw = hostBridge?.getMetadata()?.variables;
    if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
        return { ...(raw as Record<string, unknown>) };
    }
    return {};
}

function resolvePrefixDynamicDeps(blocks: readonly PromptBlock[]): {
    hasAnyDynamicDeps: boolean;
    injectKeys: string[];
    hasDynamicInjectKey: boolean;
    outletKeys: string[];
    autoPromptDynamicKeys: Layer2AutoPromptMacroKey[];
} {
    const injectKeys = new Set<string>();
    const outletKeys = new Set<string>();
    const autoPromptDynamicSet = new Set<Layer2AutoPromptMacroKey>();
    const layer2KeySet = new Set<AutoPromptMacroKey>(LAYER2_AUTO_PROMPT_KEYS);
    let hasDynamicInjectKey = false;

    for (const block of blocks) {
        const extracted = extractReferencedInjectKeys(block.content);
        for (const k of extracted.keys) {
            injectKeys.add(k);
        }
        if (extracted.hasDynamicKey) {
            hasDynamicInjectKey = true;
        }
        for (const oKey of extractReferencedOutletKeys(block.content)) {
            outletKeys.add(oKey);
        }
        for (const apKey of extractAutoPromptMacroKeys(block.content)) {
            if (layer2KeySet.has(apKey)) {
                autoPromptDynamicSet.add(apKey as Layer2AutoPromptMacroKey);
            }
        }
    }

    const autoPromptDynamicKeys = Array.from(autoPromptDynamicSet).sort(compareCodeUnits);

    return {
        hasAnyDynamicDeps:
            injectKeys.size > 0
            || hasDynamicInjectKey
            || outletKeys.size > 0
            || autoPromptDynamicKeys.length > 0,
        injectKeys: Array.from(injectKeys).sort(compareCodeUnits),
        hasDynamicInjectKey,
        outletKeys: Array.from(outletKeys).sort(compareCodeUnits),
        autoPromptDynamicKeys,
    };
}

function computePrefixDynamicFingerprint(
    deps: ReturnType<typeof resolvePrefixDynamicDeps>,
    session: PromptInjectionSession,
    outletOverrides: Record<string, string>,
    dynamicAutoPromptValues?: Partial<Record<Layer2AutoPromptMacroKey, string>>,
): string | undefined {
    if (!deps.hasAnyDynamicDeps) {
        return undefined;
    }
    const injectDigest =
        deps.injectKeys.length > 0 || deps.hasDynamicInjectKey
            ? computeInjectionDigest(session, deps.hasDynamicInjectKey ? 'all' : deps.injectKeys)
            : '';
    const outletParts = deps.outletKeys.map((k) => `${k}:${outletOverrides[`outlet:${k}`] ?? ''}`);
    const base = `${injectDigest}|${outletParts.join('\x02')}`;
    if (deps.autoPromptDynamicKeys.length === 0) {
        return base;
    }
    const autoParts = deps.autoPromptDynamicKeys.map(
        (k) => `${k}:${dynamicAutoPromptValues?.[k] ?? ''}`,
    );
    return `${base}|${autoParts.join('\x02')}`;
}

const PREFIX_MACRO_SIDE_EFFECT_RE =
    /\{\{\s*(?:(?:set|add|inc|dec)(?:global)?var\s*:{1,2}|[.$][a-zA-Z_][\w-]*\s*(?:\+\+|--|[+?-]?=|\|\|=))/i;
const PREFIX_EJS_SIDE_EFFECT_RE =
    /\b(?:setvar|setLocalVar|setGlobalVar|setMessageVar|incvar|incLocalVar|incGlobalVar|incMessageVar|decvar|decLocalVar|decGlobalVar|decMessageVar|delvar|delLocalVar|delGlobalVar|delMessageVar|insvar|insertLocalVar|insertGlobalVar|insertMessageVar|patchVariables|injectPrompt|define)\s*\(/;

/**
 * Compute deterministic `v2:` fingerprint over Layer 0 static configuration
 * (`systemBasePrompt`, `system_base`, matching `prefix` blocks, canonicalized `tools`, sorted `presetFiles` keys).
 * Excludes runtime variables so normal turns retain 100% KV Cache invariance.
 */
export function computeLayer0StaticFingerprint(input: {
    agent: Pick<AgentProfile, 'promptBlocks'>;
    tools?: readonly CanonicalToolSchema[];
    presetFiles?: Record<string, string>;
    systemBasePrompt?: string;
    promptTriggerContext?: PromptTriggerContext;
}): string {
    const promptBlocks = input.agent.promptBlocks ?? [];
    const systemBaseBlock = promptBlocks.find((b) => b.id === 'system_base');
    let systemBaseSpec: unknown;
    if (input.systemBasePrompt !== undefined) {
        systemBaseSpec = { mode: 'explicit', text: input.systemBasePrompt };
    } else if (systemBaseBlock) {
        const active =
            systemBaseBlock.enabled
            && systemBaseBlock.content.trim().length > 0
            && matchesPromptTriggers(systemBaseBlock.triggers, input.promptTriggerContext);
        systemBaseSpec = active
            ? {
                  mode: 'block',
                  id: systemBaseBlock.id,
                  role: systemBaseBlock.role,
                  content: systemBaseBlock.content,
              }
            : { mode: 'disabled' };
    } else {
        systemBaseSpec = { mode: 'default' };
    }

    const prefixBlocks = promptBlocks
        .filter(
            (b) =>
                b.enabled
                && b.placement === 'prefix'
                && b.id !== 'system_base'
                && b.content.trim().length > 0
                && matchesPromptTriggers(b.triggers, input.promptTriggerContext),
        )
        .map((b) => ({
            id: b.id,
            role: b.role,
            content: b.content,
        }));

    const presetFileNames = Object.keys(input.presetFiles ?? {})
        .map((name) => name.replace(/^\/+/, ''))
        .filter(Boolean)
        .sort(compareCodeUnits);

    const claimedAutoPrompts = detectClaimedAutoPromptMacros({
        promptBlocks,
        systemBasePrompt: input.systemBasePrompt,
        promptTriggerContext: input.promptTriggerContext,
    });
    const suppressedLayer0AutoPrompts = LAYER0_AUTO_PROMPT_KEYS.filter((k) =>
        claimedAutoPrompts.all.has(k),
    );

    const canonicalTools = canonicalizeTools(input.tools);
    const digestSource = canonicalStringify({
        systemBaseSpec,
        prefixBlocks,
        tools: canonicalTools,
        presetFileNames,
        ...(suppressedLayer0AutoPrompts.length > 0 ? { suppressedLayer0AutoPrompts } : {}),
    });
    return `v2:${hashString64Hex(digestSource)}`;
}

/**
 * Check whether a persisted `FrozenStaticPrefix` matches the active `v2:` static fingerprint
 * (and optional dynamic `getPromptsInjected` / `{{outlet::...}}` fingerprint).
 * Legacy frozen prefixes lacking a `v2:` fingerprint are treated as stale and invalidated.
 */
export function doesFrozenPrefixMatch(
    frozen: FrozenStaticPrefix | null,
    staticFingerprint: string,
    dynamicFingerprint?: string,
): boolean {
    if (!frozen || typeof frozen.prefixFingerprint !== 'string' || !frozen.prefixFingerprint.startsWith('v2:')) {
        return false;
    }
    if (dynamicFingerprint !== undefined) {
        return frozen.prefixFingerprint === `${staticFingerprint}|${dynamicFingerprint}`;
    }
    return (
        frozen.prefixFingerprint === staticFingerprint
        || frozen.prefixFingerprint.startsWith(`${staticFingerprint}|`)
    );
}

/**
 * Detect whether a `prefix` PromptBlock contains macro or EJS side effects
 * (`setvar`/`addvar`/`incvar`/`decvar`/`injectPrompt`/`define` etc.) that must still
 * execute when `frozenPrefix` hits so `tail` receives fresh per-turn state.
 */
export function hasPrefixSideEffect(content: string): boolean {
    if (!content) {
        return false;
    }
    if (PREFIX_MACRO_SIDE_EFFECT_RE.test(content)) {
        return true;
    }
    return content.includes('<%') && PREFIX_EJS_SIDE_EFFECT_RE.test(content);
}

/**
 * Whether `placement: 'tail'` PromptBlocks float transiently after `layer2Messages` /
 * `inFlightMessages` alongside `floating_tail` (unified across main, trigger, subagent,
 * Workbench, and SideGen so tool chains are sandwiched before Tail and never persisted into Layer 1).
 */
export function shouldFloatTailPromptBlocks(
    _context?: PromptTriggerContext,
): boolean {
    return true;
}

/**
 * Three-layer KV-cache-friendly Context Assembler:
 * - **Layer 0 (Static Prefix)**: canonical sorted tools + decoupled multi-character/world-simulator
 *   system base + Category ① `system_rule` compiled block + `Core Manifest` + `prefix` `PromptBlock`s.
 * - **Layer 1 (Frozen Trajectory)**: immutable finalized turns (`persistent` via `TrajectoryStore`,
 *   or sliding `ephemeralWindowSize` recent turns for `ephemeral` agents).
 * - **Layer 2 (Tail-Only Dynamic Zone)**: current user input + `<turn-brief>` + Category ④ dynamic
 *   reminders + `<lore-hint>` (plus transient `floatingTailMessages` for `tail` / `floating_tail`
 *   `PromptBlock`s appended after `inFlightMessages` without persisting into Layer 1).
 */
export class ContextAssembler {
    private readonly defaultSystemBase: string;
    private ephemeralChatTransformCache = new WeakMap<object, Map<string, string>>();

    constructor(options: { defaultSystemBase?: string } = {}) {
        this.defaultSystemBase = options.defaultSystemBase ?? createDefaultPromptBlocks()[0].content;
    }

    /**
     * Clear cached ephemeral chat-message transform results (optionally scoped to one `HostBridge`).
     * Next generation re-evaluates those messages once via `agentic_prompt_transform`.
     */
    clearEphemeralChatTransformCache(hostBridge?: object): number {
        if (hostBridge) {
            const map = this.ephemeralChatTransformCache.get(hostBridge);
            if (!map) {
                return 0;
            }
            const cleared = map.size;
            map.clear();
            return cleared;
        }
        this.ephemeralChatTransformCache = new WeakMap<object, Map<string, string>>();
        return 0;
    }

    private getEphemeralCacheForBridge(hostBridge: object): Map<string, string> {
        let map = this.ephemeralChatTransformCache.get(hostBridge);
        if (!map) {
            map = new Map<string, string>();
            this.ephemeralChatTransformCache.set(hostBridge, map);
        }
        return map;
    }

    /**
     * Compile the deterministic Layer 0 static prefix (`tools` + `messages` + `layer0EndIndex`).
     */
    compileStaticPrefix(input: {
        agent: AgentProfile;
        tools?: readonly CanonicalToolSchema[];
        characterFields?: Record<string, string>;
        personaDescription?: string;
        classifiedLore?: readonly ClassifiedLoreEntry[];
        presetFiles?: Record<string, string>;
        hollowThreshold?: number;
        systemBasePrompt?: string;
        promptTriggerContext?: PromptTriggerContext;
        preRenderedBlocks?: ReadonlyMap<string, CanonicalMessage[]>;
        preRenderedSystemRules?: readonly string[];
        macroOverrides?: Record<string, string>;
        hostBridge?: HostBridge;
    }): StaticPrefixResult {
        const canonicalTools = canonicalizeTools(input.tools);
        const promptBlocks = input.agent.promptBlocks ?? [];
        const layer0Messages: CanonicalMessage[] = [];
        const classified = input.classifiedLore ?? [];

        const claimed = detectClaimedAutoPromptMacros({
            promptBlocks,
            systemBasePrompt: input.systemBasePrompt,
            promptTriggerContext: input.promptTriggerContext,
        });

        // Pre-compute System Base, Core Manifest & System Rules so prefix blocks can reference
        // {{systemBase}} / {{coreManifest}} / {{systemRules}}.
        const { coreManifest, manifestText } = buildFormattedCoreManifest({
            characterFields: input.characterFields,
            classifiedLore: classified,
            personaDescription: input.personaDescription,
            hollowThreshold: input.hollowThreshold,
            presetFiles: input.presetFiles,
        });
        const renderedRules = renderSystemRulesSync({
            classifiedLore: classified,
            hostBridge: input.hostBridge,
            macroOverrides: input.macroOverrides,
            preRenderedSystemRules: input.preRenderedSystemRules,
        });
        const systemRulesXml = formatSystemRulesXml(renderedRules);
        const systemBaseBlock = promptBlocks.find((b) => b.id === 'system_base');
        const preRenderedSystemBaseText =
            systemBaseBlock && input.preRenderedBlocks?.has(systemBaseBlock.id)
                ? extractRenderedMessagesText(input.preRenderedBlocks.get(systemBaseBlock.id) ?? [])
                : undefined;
        const systemBaseHandling = resolveSystemBaseHandling({
            promptBlocks,
            systemBasePrompt: input.systemBasePrompt,
            promptTriggerContext: input.promptTriggerContext,
            defaultSystemBase: this.defaultSystemBase,
            claimed,
            hostBridge: input.hostBridge,
            macroOverrides: input.macroOverrides,
            preRenderedSystemBaseText,
        });
        const systemBaseText = systemBaseHandling.systemBaseText;
        const effectivePrefixMacroOverrides: Record<string, string> = {
            ...(input.macroOverrides ?? {}),
            ...buildAutoPromptMacroOverrides({
                systemBase: systemBaseText,
                coreManifest: manifestText,
                systemRules: systemRulesXml,
            }),
        };

        // 1. Decoupled System Base (multi-character / world-simulator safe; suppressed when taken over via {{systemBase}})
        if (!systemBaseHandling.suppressAutoSystemBase) {
            if (input.systemBasePrompt !== undefined) {
                const resolvedBase = substituteText(
                    input.systemBasePrompt,
                    input.hostBridge,
                    effectivePrefixMacroOverrides,
                ).trim();
                if (resolvedBase) {
                    const baseRole =
                        systemBaseBlock?.role && systemBaseBlock.role !== 'custom'
                            ? systemBaseBlock.role
                            : 'system';
                    layer0Messages.push({
                        role: baseRole,
                        content: resolvedBase,
                    });
                }
            } else if (systemBaseBlock) {
                if (
                    systemBaseBlock.enabled
                    && matchesPromptTriggers(systemBaseBlock.triggers, input.promptTriggerContext)
                ) {
                    if (input.preRenderedBlocks?.has(systemBaseBlock.id)) {
                        for (const msg of input.preRenderedBlocks.get(systemBaseBlock.id) ?? []) {
                            layer0Messages.push(canonicalClone(msg));
                        }
                    } else {
                        const rendered = renderPromptBlockSync(systemBaseBlock, {
                            hostBridge: input.hostBridge,
                            macroOverrides: effectivePrefixMacroOverrides,
                            precedingMessages: layer0Messages,
                        });
                        layer0Messages.push(...rendered);
                    }
                }
            } else {
                const resolvedBase = substituteText(
                    this.defaultSystemBase,
                    input.hostBridge,
                    effectivePrefixMacroOverrides,
                ).trim();
                if (resolvedBase) {
                    layer0Messages.push({
                        role: 'system',
                        content: resolvedBase,
                    });
                }
            }
        }

        // 2. Category ① `system_rule` compiled block (suppressed when claimed by {{systemRules}})
        if (!claimed.all.has('systemRules') && systemRulesXml) {
            layer0Messages.push({
                role: 'system',
                content: systemRulesXml,
            });
        }

        // 3. Core Manifest (/character/* + Category ② core_manifest + hollow-card notice; suppressed when claimed by {{coreManifest}})
        if (!claimed.all.has('coreManifest')) {
            layer0Messages.push({
                role: 'system',
                content: manifestText,
            });
        }

        // 4. Additional `prefix` PromptBlocks (preserving explicit order, role, and multi-message custom blocks)
        const prefixBlocks = promptBlocks.filter(
            (b: PromptBlock) =>
                b.enabled
                && b.placement === 'prefix'
                && b.id !== 'system_base'
                && b.content.trim().length > 0
                && matchesPromptTriggers(b.triggers, input.promptTriggerContext),
        );
        for (const block of prefixBlocks) {
            if (input.preRenderedBlocks?.has(block.id)) {
                for (const msg of input.preRenderedBlocks.get(block.id) ?? []) {
                    layer0Messages.push(canonicalClone(msg));
                }
            } else {
                const rendered = renderPromptBlockSync(block, {
                    hostBridge: input.hostBridge,
                    macroOverrides: effectivePrefixMacroOverrides,
                    precedingMessages: layer0Messages,
                });
                layer0Messages.push(...rendered);
            }
        }

        return {
            tools: canonicalTools,
            messages: layer0Messages,
            layer0EndIndex: layer0Messages.length - 1,
            coreManifest,
            systemRuleCount: renderedRules.length,
            systemBaseText,
            manifestText,
            systemRulesXml,
        };
    }

    /**
     * Assemble a complete three-layer `LLMRequest` (and metadata) synchronously.
     */
    assemble(input: ContextAssembleInput): AssembledContext {
        const hostBridge = input.hostBridge;
        const characterFields = input.characterFields ?? hostBridge?.getCharacterFields() ?? {};
        const personaDescription = input.personaDescription ?? hostBridge?.getPersonaDescription() ?? '';
        const classified = classifyAllEntries(input.loreEntries, input.wiRouterOverrides);
        const claimed = detectClaimedAutoPromptMacros({
            promptBlocks: input.agent.promptBlocks,
            systemBasePrompt: input.systemBasePrompt,
            promptTriggerContext: input.promptTriggerContext,
        });

        const isPersistent = input.agent.sessionMode === 'persistent';

        // Layer 1: Frozen trajectory (persistent) or sliding recent turns (ephemeral)
        let layer1Messages: CanonicalMessage[];
        if (isPersistent) {
            const stored = input.overrideLayer1Messages ?? input.trajectoryStore?.getMessages(input.agent.id) ?? [];
            layer1Messages = stored.map((m) => canonicalClone(m));
        } else {
            const windowSize = Math.max(0, input.agent.ephemeralWindowSize ?? 6);
            if (windowSize === 0 || !input.recentChatMessages?.length) {
                layer1Messages = [];
            } else {
                const canonicalHistory = toCanonicalHistoryMessages(input.recentChatMessages, input.regex);
                const { turns } = groupLayer1Turns(canonicalHistory);
                layer1Messages = turns
                    .slice(-windowSize)
                    .flatMap((t) => t.messages.map((m) => canonicalClone(m)));
            }
        }

        // Pre-compute Layer 2 dynamic auto-prompt XML values so both prefix & tail blocks can expand them.
        let consumedSideBriefPaths: string[] = [];
        let sideHintResult: SideClueRadarScanResult | undefined;
        let layer2AutoParts: {
            turnBriefXml: string;
            sideBriefXml: string;
            workspaceNoticeXml: string;
            remindersXml: string;
            loreHintXml: string;
            sideHintXml: string;
        } = {
            turnBriefXml: '',
            sideBriefXml: '',
            workspaceNoticeXml: '',
            remindersXml: '',
            loreHintXml: '',
            sideHintXml: '',
        };
        let layer2AutoOverrides: Record<string, string>;

        if (input.inFlightMessages !== undefined) {
            layer2AutoOverrides = fillMissingLayer2AutoOverrides(input.macroOverrides);
        } else {
            const briefClues = input.sideBrief === undefined && input.sideClues?.length
                ? selectUnconsumedSideBriefClues(input.sideClues)
                : [];
            consumedSideBriefPaths = briefClues.map((c) => c.path);
            const sideBriefXml = input.sideBrief !== undefined
                ? wrapXmlIfNeeded('side-brief', input.sideBrief)
                : formatSideBriefXml(briefClues);

            let sideHintXml = '';
            if (input.sideHint !== undefined) {
                if (typeof input.sideHint === 'string') {
                    sideHintXml = input.sideHint.trim();
                } else {
                    sideHintResult = input.sideHint;
                    sideHintXml = input.sideHint.hintXml.trim();
                }
            } else if (input.tailRadar && input.sideClues?.length) {
                const userText = extractUserTextForRadar(input.userInput);
                const recentTextHistory = extractRecentTexts(layer1Messages);
                if (userText || recentTextHistory.length > 0) {
                    const readSet = isPersistent
                        ? input.trajectoryStore?.getReadSet(input.agent.id)
                        : undefined;
                    sideHintResult = input.tailRadar.scanSideClues(input.sideClues, {
                        input: userText,
                        recentMessages: recentTextHistory,
                        readSet,
                        vars: input.vars,
                        macroOverrides: input.macroOverrides,
                    });
                    sideHintXml = sideHintResult.hintXml.trim();
                }
            }

            const baseLayer2MacroOverrides = buildLayer2MacroOverrides(input.vars, input.macroOverrides);
            const reminderLines: string[] = [];
            if (input.includeCategory4DynamicEntries !== false) {
                if (input.preRenderedDynamicReminders !== undefined) {
                    for (const line of input.preRenderedDynamicReminders) {
                        const trimmed = line.trim();
                        if (trimmed) {
                            reminderLines.push(trimmed);
                        }
                    }
                } else {
                    const dynamicEntries = classified
                        .filter(
                            (item) =>
                                item.category === 'dynamic_or_trigger'
                                && !item.entry.disable
                                && (item.reason === 'dynamic_at_depth' || item.reason === 'conditional_dynamic'),
                        )
                        .sort(
                            (a, b) =>
                                b.entry.order - a.entry.order
                                || a.entry.depth - b.entry.depth
                                || compareCodeUnits(a.entry.world, b.entry.world)
                                || a.entry.uid - b.entry.uid,
                        );
                    for (const item of dynamicEntries) {
                        const rendered = substituteText(
                            item.cleanContent,
                            input.hostBridge,
                            baseLayer2MacroOverrides,
                        ).trim();
                        if (rendered) {
                            reminderLines.push(rendered);
                        }
                    }
                }
            }
            if (input.dynamicReminders) {
                for (const line of input.dynamicReminders) {
                    const trimmed = line.trim();
                    if (trimmed) {
                        reminderLines.push(trimmed);
                    }
                }
            }

            const turnBriefXml = input.turnBrief ? wrapXmlIfNeeded('turn-brief', input.turnBrief) : '';
            const workspaceNoticeXml = input.workspaceNotice?.trim() ?? '';
            const remindersXml = formatDynamicRemindersXml(reminderLines);
            const loreHintXml = typeof input.loreHint === 'string'
                ? input.loreHint.trim()
                : (input.loreHint?.hintXml?.trim() ?? '');

            layer2AutoParts = {
                turnBriefXml,
                sideBriefXml,
                workspaceNoticeXml,
                remindersXml,
                loreHintXml,
                sideHintXml,
            };
            layer2AutoOverrides = buildAutoPromptMacroOverrides({
                turnBrief: turnBriefXml,
                sideBrief: sideBriefXml,
                workspaceNotice: workspaceNoticeXml,
                dynamicReminders: remindersXml,
                loreHint: loreHintXml,
                sideHint: sideHintXml,
            });
        }

        const prefixInputMacroOverrides: Record<string, string> = {
            ...(input.macroOverrides ?? {}),
            ...layer2AutoOverrides,
        };

        let layer0Messages: CanonicalMessage[];
        let tools: CanonicalToolSchema[];
        let layer0EndIndex: number;
        let coreManifest: CoreManifestResult;
        let systemRuleCount: number;
        let systemBaseText: string;
        let manifestText: string;
        let systemRulesXml: string;

        const hasTriggerScopedBlocks = (input.agent.promptBlocks ?? []).some(
            (b) => b.triggers && b.triggers.length > 0,
        );
        const isNonMainTriggerRun =
            isPersistent
            && input.promptTriggerContext !== undefined
            && input.promptTriggerContext.kind !== 'main'
            && hasTriggerScopedBlocks;
        const staticFingerprint = computeLayer0StaticFingerprint({
            agent: input.agent,
            tools: input.tools,
            presetFiles: input.presetFiles,
            systemBasePrompt: input.systemBasePrompt,
            promptTriggerContext: input.promptTriggerContext,
        });
        const expectedFingerprint = input.prefixFingerprint ?? staticFingerprint;
        const rawFrozen =
            isPersistent && !input.forceRecompilePrefix && !isNonMainTriggerRun
                ? input.trajectoryStore?.getFrozenPrefix(input.agent.id) ?? null
                : null;
        const existingFrozen =
            rawFrozen
            && (input.prefixFingerprint !== undefined
                ? rawFrozen.prefixFingerprint === input.prefixFingerprint
                : doesFrozenPrefixMatch(rawFrozen, staticFingerprint))
                ? rawFrozen
                : null;

        if (existingFrozen) {
            tools = canonicalClone(existingFrozen.tools) as CanonicalToolSchema[];
            layer0Messages = canonicalClone(existingFrozen.messages) as CanonicalMessage[];
            layer0EndIndex = existingFrozen.layer0EndIndex;
            const formatted = buildFormattedCoreManifest({
                characterFields,
                classifiedLore: classified,
                personaDescription,
                hollowThreshold: input.hollowThreshold,
                presetFiles: input.presetFiles,
            });
            coreManifest = formatted.coreManifest;
            manifestText = formatted.manifestText;
            systemRuleCount = classified.filter(
                (item) => item.category === 'system_rule' && !item.entry.disable,
            ).length;
            systemRulesXml = claimed.tail.has('systemRules')
                ? formatSystemRulesXml(
                      renderSystemRulesSync({
                          classifiedLore: classified,
                          hostBridge,
                          macroOverrides: prefixInputMacroOverrides,
                          preRenderedSystemRules: input.preRenderedSystemRules,
                      }),
                  )
                : '';
            const frozenBaseBlock = (input.agent.promptBlocks ?? []).find(
                (b) => b.id === 'system_base',
            );
            const preRenderedFrozenBaseText =
                frozenBaseBlock && input.preRenderedBlocks?.has(frozenBaseBlock.id)
                    ? extractRenderedMessagesText(input.preRenderedBlocks.get(frozenBaseBlock.id) ?? [])
                    : undefined;
            systemBaseText = resolveSystemBaseHandling({
                promptBlocks: input.agent.promptBlocks,
                systemBasePrompt: input.systemBasePrompt,
                promptTriggerContext: input.promptTriggerContext,
                defaultSystemBase: this.defaultSystemBase,
                claimed,
                hostBridge,
                macroOverrides: prefixInputMacroOverrides,
                preRenderedSystemBaseText: preRenderedFrozenBaseText,
            }).systemBaseText;
        } else {
            const prefix = this.compileStaticPrefix({
                agent: input.agent,
                tools: input.tools,
                characterFields,
                personaDescription,
                classifiedLore: classified,
                presetFiles: input.presetFiles,
                hollowThreshold: input.hollowThreshold,
                systemBasePrompt: input.systemBasePrompt,
                promptTriggerContext: input.promptTriggerContext,
                preRenderedBlocks: input.preRenderedBlocks,
                preRenderedSystemRules: input.preRenderedSystemRules,
                macroOverrides: prefixInputMacroOverrides,
                hostBridge,
            });
            tools = prefix.tools;
            layer0Messages = prefix.messages;
            layer0EndIndex = prefix.layer0EndIndex;
            coreManifest = prefix.coreManifest;
            systemRuleCount = prefix.systemRuleCount;
            systemBaseText = prefix.systemBaseText;
            manifestText = prefix.manifestText;
            systemRulesXml = prefix.systemRulesXml;

            if (isPersistent && !isNonMainTriggerRun && input.trajectoryStore) {
                input.trajectoryStore.setFrozenPrefix(
                    {
                        tools,
                        messages: layer0Messages,
                        layer0EndIndex,
                        prefixFingerprint: expectedFingerprint,
                        ...(input.cachedPrefixBlocks
                            ? { cachedPrefixBlocks: input.cachedPrefixBlocks }
                            : {}),
                        ...(input.cachedSystemRules
                            ? { cachedSystemRules: input.cachedSystemRules }
                            : {}),
                        ...(input.nonCacheablePrefixBlockIds?.length
                            ? { nonCacheablePrefixBlockIds: input.nonCacheablePrefixBlockIds }
                            : {}),
                        ...(input.nonCacheableSystemRuleKeys?.length
                            ? { nonCacheableSystemRuleKeys: input.nonCacheableSystemRuleKeys }
                            : {}),
                        ...(input.prefixHookCacheKeys
                            && Object.keys(input.prefixHookCacheKeys).length > 0
                            ? { prefixHookCacheKeys: input.prefixHookCacheKeys }
                            : {}),
                    },
                    input.agent.id,
                );
            }
        }

        const effectiveMacroOverrides: Record<string, string> = {
            ...prefixInputMacroOverrides,
            ...buildAutoPromptMacroOverrides({
                systemBase: systemBaseText,
                coreManifest: manifestText,
                systemRules: systemRulesXml,
            }),
        };

        // Layer 2: Tail-Only Dynamic Zone (or frozen in-flight messages during tool loop)
        let layer2Messages: CanonicalMessage[];
        if (input.inFlightMessages !== undefined) {
            layer2Messages = input.inFlightMessages.map((m) => canonicalClone(m));
        } else {
            layer2Messages = this.buildLayer2Messages(
                input,
                layer2AutoParts,
                claimed,
                effectiveMacroOverrides,
            );
        }

        const floatingTailMessages = this.buildFloatingTailMessages(
            input,
            [
                ...layer0Messages,
                ...layer1Messages,
                ...layer2Messages,
            ],
            effectiveMacroOverrides,
        );

        const allMessages = [
            ...layer0Messages,
            ...layer1Messages,
            ...layer2Messages,
            ...floatingTailMessages,
        ];
        const layer1EndIndex = layer0Messages.length + layer1Messages.length - 1;

        const cacheBreakpoints = this.computeCacheBreakpoints({
            layer0Count: layer0Messages.length,
            layer0EndIndex,
            layer1Count: layer1Messages.length,
            layer1EndIndex,
            isPersistent,
            trajectoryStore: input.trajectoryStore,
            agentId: input.agent.id,
        });

        const request: LLMRequest = {
            connectionId: input.connectionId ?? input.agent.connectionId,
            messages: allMessages,
            tools,
            ...(cacheBreakpoints.length > 0 ? { cacheBreakpoints } : {}),
            ...(input.signal ? { signal: input.signal } : {}),
        };

        const estimatedTokens = estimateRequestTokens(allMessages, tools);

        return {
            request,
            layer0Messages,
            layer1Messages,
            layer2Messages,
            floatingTailMessages,
            cacheBreakpoints,
            coreManifest,
            systemRuleCount,
            consumedSideBriefPaths,
            ...(sideHintResult !== undefined ? { sideHintResult } : {}),
            ...(input.preRenderedBlocks ? { preRenderedBlocks: input.preRenderedBlocks } : {}),
            ...(input.preRenderedSystemRules !== undefined
                ? { preRenderedSystemRules: input.preRenderedSystemRules }
                : {}),
            ...(Object.keys(effectiveMacroOverrides).length > 0 ? { effectiveMacroOverrides } : {}),
            stats: {
                layer0MessageCount: layer0Messages.length,
                layer1MessageCount: layer1Messages.length,
                layer2MessageCount: layer2Messages.length,
                floatingTailMessageCount: floatingTailMessages.length,
                totalMessageCount: allMessages.length,
                layer0EndIndex,
                layer1EndIndex,
                estimatedTokens,
            },
        };
    }

    /**
     * Async convenience wrapper pulling lorebooks/character/persona from `HostBridge`,
     * optionally enumerating `/side/*` clues from `vfs`, and scanning Category ③ + `/side/*`
     * entries via `TailRadar` against `TrajectoryStore`'s `Read-Set`.
     */
    async assembleWithHost(input: AssembleWithHostInput): Promise<AssembledContext> {
        const {
            hostBridge,
            tailRadar,
            vfs,
            target,
            runTailRadar = true,
            injectionSession,
            transformSessionId: providedTransformSessionId,
            transformPhase: providedTransformPhase,
            transformSessionBag: providedTransformSessionBag,
            canEditPath,
            canWritePath,
            userInputIsChatMessage,
            userMessageMeta,
            ...rest
        } = input;

        const transformSessionId =
            providedTransformSessionId
            ?? `turn_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
        const transformSessionBag = providedTransformSessionBag ?? {};
        const transformPhase =
            providedTransformPhase
            ?? (rest.promptTriggerContext && 'phase' in rest.promptTriggerContext
                ? rest.promptTriggerContext.phase
                : undefined)
            ?? 'main_turn';
        const transformTarget: MessageTarget | undefined =
            target
            ?? (() => {
                const chatList = hostBridge.getChat();
                if (chatList.length === 0) {
                    return undefined;
                }
                const lastIdx = chatList.length - 1;
                return {
                    messageId: lastIdx,
                    swipeId: chatList[lastIdx]?.swipeId ?? 0,
                };
            })();

        let loreEntries = rest.loreEntries;
        if (!loreEntries) {
            const books = await hostBridge.listEnabledLorebooks();
            const raw: RawLoreEntry[] = [];
            for (const [world, entries] of books.entries()) {
                for (const entry of entries) {
                    raw.push(entry.world ? entry : { ...entry, world });
                }
            }
            loreEntries = raw;
        }

        let sideClues = rest.sideClues;
        if (sideClues === undefined && vfs) {
            sideClues = await vfs.listSideClues(target);
        }

        const userText = extractUserTextForRadar(rest.userInput);
        const readSet = rest.agent.sessionMode === 'persistent'
            ? rest.trajectoryStore?.getReadSet(rest.agent.id)
            : undefined;
        const recentTextHistory = extractRecentTexts(
            rest.agent.sessionMode === 'persistent'
                ? (rest.trajectoryStore?.getMessages(rest.agent.id) ?? [])
                : [],
        );

        const session: PromptInjectionSession =
            injectionSession
            ?? hostBridge.createPromptInjectionSession?.().session
            ?? new LocalPromptInjectionSession();

        const effectiveVars: Record<string, unknown> = {
            ...extractMetadataVarsFallback(hostBridge),
            ...(rest.vars ?? {}),
        };
        const liveVars: Record<string, unknown> = { ...effectiveVars };
        const mutatedTurnVars: Record<string, unknown> = {};
        const ejsSession: EjsRenderSession = {};
        const applyTurnVarUpdates = (updates: Record<string, unknown>): void => {
            for (const [k, v] of Object.entries(updates)) {
                liveVars[k] = v;
                mutatedTurnVars[k] = v;
            }
        };
        const syncMetadataVarDiff = (beforeVars: Record<string, unknown>): void => {
            const afterVars = extractMetadataVarsFallback(hostBridge);
            const delta: Record<string, unknown> = {};
            let changed = false;
            for (const [k, v] of Object.entries(afterVars)) {
                if (!Object.hasOwn(beforeVars, k) || canonicalStringify(beforeVars[k]) !== canonicalStringify(v)) {
                    delta[k] = v;
                    changed = true;
                }
            }
            if (changed) {
                applyTurnVarUpdates(delta);
                ejsSession.pendingMacroVarUpdates = {
                    ...(ejsSession.pendingMacroVarUpdates ?? {}),
                    ...delta,
                };
            }
        };
        const transformTextWithTurnSync = async (
            text: string,
            varsSnapshot: Record<string, unknown>,
            opts: {
                source: PromptTransformSource;
                layer: PromptTransformLayer;
                role?: PromptTransformRole;
                dryRun?: boolean;
                isPrivate?: boolean;
                lore?: PromptTransformLoreMeta;
                isChatMessage?: boolean;
                messageId?: number;
                swipeId?: number;
                name?: string;
                isUser?: boolean;
            },
        ): Promise<PromptTransformResult> => {
            if (!hostBridge.transformPromptText && !hostBridge.evaluateOptionalEjs) {
                return createNoopPromptTransformResult(text);
            }
            const preSnap = extractMetadataVarsFallback(hostBridge);
            const result = await runPromptTransform(hostBridge, {
                text,
                source: opts.source,
                layer: opts.layer,
                ...(opts.role !== undefined ? { role: opts.role } : {}),
                dryRun: Boolean(opts.dryRun),
                meta: {
                    sessionId: transformSessionId,
                    agentId: rest.agent.id,
                    phase: transformPhase,
                    ...(transformTarget ? { target: transformTarget } : {}),
                    isChatMessage: Boolean(opts.isChatMessage),
                    ...(opts.messageId !== undefined ? { messageId: opts.messageId } : {}),
                    ...(opts.swipeId !== undefined ? { swipeId: opts.swipeId } : {}),
                    ...(opts.name !== undefined ? { name: opts.name } : {}),
                    ...(opts.isUser !== undefined ? { isUser: opts.isUser } : {}),
                    ...(opts.lore ? { lore: opts.lore } : {}),
                    vars: varsSnapshot,
                    ...(opts.isPrivate ? { isPrivate: true } : {}),
                    injectionSession: session,
                    ejsSession,
                },
                sessionBag: transformSessionBag,
                ...(rest.signal ? { signal: rest.signal } : {}),
                onError: 'fallback',
            });
            const postSnap = extractMetadataVarsFallback(hostBridge);
            const delta: Record<string, unknown> = {};
            for (const [k, v] of Object.entries(postSnap)) {
                if (!Object.hasOwn(preSnap, k) || canonicalStringify(preSnap[k]) !== canonicalStringify(v)) {
                    delta[k] = v;
                }
            }
            if (ejsSession.lastEjsVarUpdates) {
                Object.assign(delta, ejsSession.lastEjsVarUpdates);
                ejsSession.lastEjsVarUpdates = undefined;
            }
            if (Object.keys(delta).length > 0) {
                applyTurnVarUpdates(delta);
            }
            return result;
        };

        await hostBridge.notifyPromptTransformTurnStart?.({
            version: 1,
            sessionId: transformSessionId,
            agentId: rest.agent.id,
            phase: transformPhase,
            ...(transformTarget
                ? {
                      target: transformTarget,
                      messageId: transformTarget.messageId,
                      swipeId: transformTarget.swipeId,
                  }
                : {}),
            vars: liveVars,
            sessionBag: transformSessionBag,
            ...(rest.signal ? { signal: rest.signal } : {}),
        });

        try {
        const invertEnabled = Boolean(hostBridge.getEjsFeatures?.()?.invertEnabled);
        const classified = classifyAllEntries(loreEntries, rest.wiRouterOverrides);
        const keywordHaystack = userText
            ? (recentTextHistory.length > 0 ? `${recentTextHistory.join('\n')}\n${userText}` : userText)
            : recentTextHistory.join('\n');

        // Step A: World Info `injectPrompt` pre-collection pass (e.g. @@generate_before / [GENERATE:BEFORE] / pure scripts)
        if (rest.inFlightMessages === undefined && loreEntries.length > 0) {
            const preCollectCandidates: Array<{
                entry: RawLoreEntry;
                decorators: ReturnType<typeof DecoratorParser.parseEntry>['decorators'];
                cleanContent: string;
            }> = [];

            for (const rawItem of loreEntries) {
                const entry = isClassifiedLoreEntry(rawItem) ? rawItem.entry : rawItem;
                const parsed = DecoratorParser.parseEntry(entry);
                if (parsed.decorators.some((d) => PRECOLLECT_EXCLUDED_DECORATORS.has(d.name))) {
                    continue;
                }
                if (isEjsForceDisabledEntry(parsed.decorators)) {
                    continue;
                }

                const isGenBefore = isEjsGenerateBeforeEntry(entry, parsed.decorators, parsed.cleanContent);
                const enabled = isEjsEntryEnabled(entry, parsed.decorators, { invertEnabled });
                if (!enabled) {
                    continue;
                }

                const isSpecial = isEjsSpecialEntry(entry, parsed.decorators);
                if (isSpecial && !isGenBefore) {
                    continue;
                }

                const isPreCollect =
                    isGenBefore
                    || (parsed.cleanContent.includes('<%') && parsed.cleanContent.includes('injectPrompt('))
                    || (classifyEntry(entry, { overrides: rest.wiRouterOverrides }).reason === 'pure_script');
                if (!isPreCollect) {
                    continue;
                }

                if (!entry.constant) {
                    if (!keywordHaystack || !Array.isArray(entry.keys) || entry.keys.length === 0) {
                        continue;
                    }
                    const matched = matchLoreEntryKeywords(entry, keywordHaystack, {
                        substituteMacros: (t, ov) => hostBridge.substituteMacros(t, ov),
                        macroOverrides: buildLayer2MacroOverrides(effectiveVars, rest.macroOverrides),
                    });
                    if (!matched) {
                        continue;
                    }
                }

                preCollectCandidates.push({
                    entry,
                    decorators: parsed.decorators,
                    cleanContent: parsed.cleanContent,
                });
            }

            preCollectCandidates.sort(
                (a, b) =>
                    b.entry.order - a.entry.order
                    || a.entry.depth - b.entry.depth
                    || compareCodeUnits(a.entry.world, b.entry.world)
                    || a.entry.uid - b.entry.uid,
            );

            for (const item of preCollectCandidates) {
                const ifConds = extractIfConditions(item.decorators);
                const passed = await evaluateIfConditions(ifConds, hostBridge, liveVars, {
                    injectionSession: session,
                });
                if (!passed) {
                    continue;
                }
                const preMacroVars = extractMetadataVarsFallback(hostBridge);
                const itemOverrides = buildLayer2MacroOverrides(
                    Object.keys(mutatedTurnVars).length > 0
                        ? { ...(rest.vars ?? {}), ...mutatedTurnVars }
                        : rest.vars,
                    rest.macroOverrides,
                );
                const substituted = hostBridge.substituteMacros(item.cleanContent, itemOverrides);
                syncMetadataVarDiff(preMacroVars);
                if (hostBridge.transformPromptText || (hostBridge.evaluateOptionalEjs && substituted.includes('<%'))) {
                    await transformTextWithTurnSync(substituted, liveVars, {
                        source: 'lore_precollect',
                        layer: 'trigger',
                        isPrivate: hasPrivateDecorator(item.decorators),
                        lore: {
                            world: item.entry.world,
                            uid: item.entry.uid,
                            comment: item.entry.comment ?? '',
                            overridden: false,
                        },
                    });
                }
            }
        }

        // Step B: TailRadar scan (passing shared injectionSession so @@if & EJS inside Category ③ see pre-collected injections)
        let loreHint = rest.loreHint;
        const shouldScanLoreRadar =
            runTailRadar
            && loreHint === undefined
            && rest.inFlightMessages === undefined
            && tailRadar !== undefined;

        if (shouldScanLoreRadar && tailRadar && userText) {
            loreHint = await tailRadar.scan(classified, {
                input: userText,
                recentMessages: recentTextHistory,
                readSet,
                target,
                vars: rest.vars,
                macroOverrides: rest.macroOverrides,
                injectionSession: session,
                canEditPath,
                canWritePath,
                sessionId: transformSessionId,
                agentId: rest.agent.id,
                phase: transformPhase,
                sessionBag: transformSessionBag,
            });
        }

        let sideHint = rest.sideHint;
        const shouldScanSideRadar =
            runTailRadar
            && sideHint === undefined
            && rest.inFlightMessages === undefined
            && tailRadar !== undefined
            && Boolean(sideClues && sideClues.length > 0);

        if (shouldScanSideRadar && tailRadar && sideClues && (userText || recentTextHistory.length > 0)) {
            sideHint = tailRadar.scanSideClues(sideClues, {
                input: userText,
                recentMessages: recentTextHistory,
                readSet,
                vars: rest.vars,
                macroOverrides: rest.macroOverrides,
            });
        }

        const preRenderedBlocks = new Map<string, CanonicalMessage[]>(
            rest.preRenderedBlocks ? Array.from(rest.preRenderedBlocks.entries()) : [],
        );
        const promptBlocks = rest.agent.promptBlocks ?? [];
        const isPersistent = rest.agent.sessionMode === 'persistent';
        const hasTriggerScopedBlocks = promptBlocks.some(
            (b) => b.triggers && b.triggers.length > 0,
        );
        const isNonMainTriggerRun =
            isPersistent
            && rest.promptTriggerContext !== undefined
            && rest.promptTriggerContext.kind !== 'main'
            && hasTriggerScopedBlocks;
        const existingFrozen =
            isPersistent
            && !rest.forceRecompilePrefix
            && !isNonMainTriggerRun
                ? rest.trajectoryStore?.getFrozenPrefix(rest.agent.id) ?? null
                : null;

        // Step C: Build ST native `{{outlet::key}}` table for this turn (using forceOutlet=true so nested getPromptsInjected supports forward refs)
        const outletMacroOverrides: Record<string, string> = {
            __has_outlet_table__: '1',
        };
        const outletEntries = classified
            .filter(
                (item) =>
                    !item.entry.disable
                    && item.entry.position === WORLD_INFO_POSITION.outlet
                    && Boolean(item.entry.outletName?.trim())
                    && !isEjsForceDisabledEntry(item.decorators),
            )
            .sort(
                (a, b) =>
                    b.entry.order - a.entry.order
                    || a.entry.depth - b.entry.depth
                    || compareCodeUnits(a.entry.world, b.entry.world)
                    || a.entry.uid - b.entry.uid,
            );

        if (outletEntries.length > 0) {
            const outletBuckets = new Map<string, string[]>();
            const outletEvaluator = new LoreReadEvaluator(hostBridge);
            const baseMacroOverrides = buildLayer2MacroOverrides(effectiveVars, rest.macroOverrides);

            session.setForceOutlet(true);
            try {
                for (const item of outletEntries) {
                    const outletName = item.entry.outletName?.trim();
                    if (!outletName) {
                        continue;
                    }
                    if (!item.entry.constant) {
                        if (!keywordHaystack || !Array.isArray(item.entry.keys) || item.entry.keys.length === 0) {
                            continue;
                        }
                        const matched = matchLoreEntryKeywords(item.entry, keywordHaystack, {
                            substituteMacros: (t, ov) => hostBridge.substituteMacros(t, ov),
                            macroOverrides: baseMacroOverrides,
                        });
                        if (!matched) {
                            continue;
                        }
                    }

                    const evaluated = await outletEvaluator.evaluate(item, {
                        target,
                        vars: effectiveVars,
                        macroOverrides: baseMacroOverrides,
                        injectionSession: session,
                        source: 'lore_outlet',
                        sessionId: transformSessionId,
                        agentId: rest.agent.id,
                        phase: transformPhase,
                        sessionBag: transformSessionBag,
                    });
                    if (evaluated.conditionSkipped || !evaluated.text.trim()) {
                        continue;
                    }
                    const list = outletBuckets.get(outletName) ?? [];
                    list.push(evaluated.text.trim());
                    outletBuckets.set(outletName, list);
                }
            } finally {
                session.setForceOutlet(false);
            }

            for (const [key, parts] of outletBuckets.entries()) {
                outletMacroOverrides[`outlet:${key}`] = parts.join('\n');
            }
        }

        const combinedMacroOverrides: Record<string, string> = {
            ...(rest.macroOverrides ?? {}),
            ...outletMacroOverrides,
        };

        // Determine matching prefix blocks and check Layer 0 dynamic dirty fingerprint
        const characterFields = rest.characterFields ?? hostBridge.getCharacterFields() ?? {};
        const personaDescription = rest.personaDescription ?? hostBridge.getPersonaDescription() ?? '';
        const claimed = detectClaimedAutoPromptMacros({
            promptBlocks,
            systemBasePrompt: rest.systemBasePrompt,
            promptTriggerContext: rest.promptTriggerContext,
        });
        const { manifestText } = buildFormattedCoreManifest({
            characterFields,
            classifiedLore: classified,
            personaDescription,
            hollowThreshold: rest.hollowThreshold,
            presetFiles: rest.presetFiles,
        });
        const systemBaseHandling = resolveSystemBaseHandling({
            promptBlocks,
            systemBasePrompt: rest.systemBasePrompt,
            promptTriggerContext: rest.promptTriggerContext,
            defaultSystemBase: this.defaultSystemBase,
            claimed,
            hostBridge,
            macroOverrides: combinedMacroOverrides,
        });
        let resolvedSystemBaseText = systemBaseHandling.systemBaseText;

        const turnBriefXml =
            rest.inFlightMessages === undefined && rest.turnBrief
                ? wrapXmlIfNeeded('turn-brief', rest.turnBrief)
                : '';
        const sideBriefXml =
            rest.inFlightMessages === undefined
                ? (rest.sideBrief !== undefined
                      ? wrapXmlIfNeeded('side-brief', rest.sideBrief)
                      : formatSideBriefXml(
                            sideClues?.length ? selectUnconsumedSideBriefClues(sideClues) : [],
                        ))
                : '';
        const workspaceNoticeXml =
            rest.inFlightMessages === undefined ? (rest.workspaceNotice?.trim() ?? '') : '';
        const loreHintXml =
            rest.inFlightMessages === undefined
                ? (typeof loreHint === 'string'
                      ? loreHint.trim()
                      : (loreHint?.hintXml?.trim() ?? ''))
                : '';
        const sideHintXml =
            rest.inFlightMessages === undefined
                ? (typeof sideHint === 'string'
                      ? sideHint.trim()
                      : (sideHint?.hintXml?.trim() ?? ''))
                : '';

        const matchingPrefixBlocks: PromptBlock[] = [];
        const systemBaseBlock = promptBlocks.find((b) => b.id === 'system_base');
        if (
            rest.systemBasePrompt === undefined
            && systemBaseBlock
            && systemBaseBlock.enabled
            && systemBaseBlock.content.trim().length > 0
            && matchesPromptTriggers(systemBaseBlock.triggers, rest.promptTriggerContext)
        ) {
            matchingPrefixBlocks.push(systemBaseBlock);
        }
        for (const block of promptBlocks) {
            if (
                block.enabled
                && block.placement === 'prefix'
                && block.id !== 'system_base'
                && block.content.trim().length > 0
                && matchesPromptTriggers(block.triggers, rest.promptTriggerContext)
            ) {
                matchingPrefixBlocks.push(block);
            }
        }

        const staticPrefixFingerprint = computeLayer0StaticFingerprint({
            agent: rest.agent,
            tools: rest.tools,
            presetFiles: rest.presetFiles,
            systemBasePrompt: rest.systemBasePrompt,
            promptTriggerContext: rest.promptTriggerContext,
        });
        const prefixDeps = resolvePrefixDynamicDeps(matchingPrefixBlocks);

        let preRenderedSystemRules: string[] | undefined = rest.preRenderedSystemRules
            ? [...rest.preRenderedSystemRules]
            : undefined;
        let preRenderedDynamicReminders: string[] | undefined = rest.preRenderedDynamicReminders
            ? [...rest.preRenderedDynamicReminders]
            : undefined;

        const systemRuleEntries = classified
            .filter((item) => item.category === 'system_rule' && !item.entry.disable)
            .sort(
                (a, b) =>
                    b.entry.order - a.entry.order
                    || a.entry.depth - b.entry.depth
                    || compareCodeUnits(a.entry.world, b.entry.world)
                    || a.entry.uid - b.entry.uid,
            );
        const systemRuleCacheKey = (item: ClassifiedLoreEntry): string =>
            `${item.entry.world}\0${item.entry.uid}`;

        const renderSystemRulesAsync = async (ruleOpts?: {
            onlyKeys?: ReadonlySet<string>;
            cachedByKey?: Readonly<Record<string, string>>;
            applyOutlets?: boolean;
        }): Promise<{
            renderedRules: string[];
            ruleTextByKey: Record<string, string>;
            nonCacheableKeys: string[];
            cacheKeys: Record<string, string>;
            changed: boolean;
        }> => {
            const renderedRulesList: string[] = [];
            const ruleTextByKey: Record<string, string> = {};
            const nonCacheableKeys: string[] = [];
            const cacheKeys: Record<string, string> = {};
            let changed = false;

            for (const item of systemRuleEntries) {
                const key = systemRuleCacheKey(item);
                if (ruleOpts?.onlyKeys && !ruleOpts.onlyKeys.has(key)) {
                    const cachedRule = ruleOpts.cachedByKey?.[key] ?? '';
                    ruleTextByKey[key] = cachedRule;
                    if (cachedRule) {
                        renderedRulesList.push(cachedRule);
                    }
                    continue;
                }

                const ifConds = extractIfConditions(item.decorators);
                const passed = await evaluateIfConditions(ifConds, hostBridge, liveVars, {
                    injectionSession: session,
                });
                if (!passed) {
                    ruleTextByKey[key] = '';
                    if (ruleOpts?.cachedByKey && (ruleOpts.cachedByKey[key] ?? '') !== '') {
                        changed = true;
                    }
                    continue;
                }
                const preMacroVars = extractMetadataVarsFallback(hostBridge);
                let text = substituteText(item.cleanContent, hostBridge, combinedMacroOverrides);
                syncMetadataVarDiff(preMacroVars);
                if (hostBridge.transformPromptText || (hostBridge.evaluateOptionalEjs && text.includes('<%'))) {
                    const res = await transformTextWithTurnSync(text, liveVars, {
                        source: 'system_rule',
                        layer: 'layer0_prefix',
                        role: 'system',
                        isPrivate: hasPrivateDecorator(item.decorators),
                        lore: {
                            world: item.entry.world,
                            uid: item.entry.uid,
                            comment: item.entry.comment ?? '',
                            overridden: Boolean(item.overridden),
                        },
                    });
                    text = res.text;
                    if (!res.cacheable) {
                        nonCacheableKeys.push(key);
                    }
                    Object.assign(cacheKeys, res.cacheKeys);
                }
                const trimmed = text.trim();
                const title = item.entry.comment?.trim();
                let formatted = trimmed ? (title ? `### ${title}\n${trimmed}` : trimmed) : '';
                if (ruleOpts?.applyOutlets && formatted) {
                    formatted = session.applyOutlets(formatted).trim();
                }
                ruleTextByKey[key] = formatted;
                if (ruleOpts?.cachedByKey && formatted !== (ruleOpts.cachedByKey[key] ?? '')) {
                    changed = true;
                }
                if (formatted) {
                    renderedRulesList.push(formatted);
                }
            }
            return {
                renderedRules: renderedRulesList,
                ruleTextByKey,
                nonCacheableKeys,
                cacheKeys,
                changed,
            };
        };

        const renderDynamicRemindersAsync = async (
            varsSnapshot: Record<string, unknown>,
            overridesSnapshot: Record<string, string> | undefined,
        ): Promise<string[]> => {
            const dynamicEntries = classified
                .filter(
                    (item) =>
                        item.category === 'dynamic_or_trigger'
                        && !item.entry.disable
                        && (item.reason === 'dynamic_at_depth' || item.reason === 'conditional_dynamic'),
                )
                .sort(
                    (a, b) =>
                        b.entry.order - a.entry.order
                        || a.entry.depth - b.entry.depth
                        || compareCodeUnits(a.entry.world, b.entry.world)
                        || a.entry.uid - b.entry.uid,
                );
            const renderedReminders: string[] = [];
            for (const item of dynamicEntries) {
                const ifConds = extractIfConditions(item.decorators);
                const passed = await evaluateIfConditions(ifConds, hostBridge, varsSnapshot, {
                    injectionSession: session,
                });
                if (!passed) {
                    continue;
                }
                const preMacroVars = extractMetadataVarsFallback(hostBridge);
                let text = substituteText(item.cleanContent, hostBridge, overridesSnapshot);
                syncMetadataVarDiff(preMacroVars);
                if (hostBridge.transformPromptText || (hostBridge.evaluateOptionalEjs && text.includes('<%'))) {
                    const res = await transformTextWithTurnSync(text, varsSnapshot, {
                        source: 'dynamic_reminder',
                        layer: 'layer2_tail',
                        role: 'user',
                        isPrivate: hasPrivateDecorator(item.decorators),
                        lore: {
                            world: item.entry.world,
                            uid: item.entry.uid,
                            comment: item.entry.comment ?? '',
                            overridden: Boolean(item.overridden),
                        },
                    });
                    text = res.text;
                }
                const trimmed = text.trim();
                if (trimmed) {
                    renderedReminders.push(trimmed);
                }
            }
            return renderedReminders;
        };

        if (
            rest.inFlightMessages === undefined
            && prefixDeps.autoPromptDynamicKeys.includes('dynamicReminders')
            && rest.includeCategory4DynamicEntries !== false
            && preRenderedDynamicReminders === undefined
        ) {
            session.setForceOutlet(true);
            try {
                const preDynamicOverrides = buildLayer2MacroOverrides(liveVars, {
                    ...combinedMacroOverrides,
                    ...buildAutoPromptMacroOverrides({
                        systemBase: resolvedSystemBaseText,
                        coreManifest: manifestText,
                        turnBrief: turnBriefXml,
                        sideBrief: sideBriefXml,
                        workspaceNotice: workspaceNoticeXml,
                        loreHint: loreHintXml,
                        sideHint: sideHintXml,
                    }),
                });
                preRenderedDynamicReminders = await renderDynamicRemindersAsync(
                    liveVars,
                    preDynamicOverrides,
                );
            } finally {
                session.setForceOutlet(false);
            }
        }

        const buildDynamicAutoPromptFingerprintValues = (): Partial<
            Record<Layer2AutoPromptMacroKey, string>
        > => {
            if (rest.inFlightMessages !== undefined) {
                return {
                    turnBrief: rest.macroOverrides?.turnBrief ?? '',
                    sideBrief: rest.macroOverrides?.sideBrief ?? '',
                    workspaceNotice: rest.macroOverrides?.workspaceNotice ?? '',
                    dynamicReminders: rest.macroOverrides?.dynamicReminders ?? '',
                    loreHint: rest.macroOverrides?.loreHint ?? '',
                    sideHint: rest.macroOverrides?.sideHint ?? '',
                };
            }
            return {
                turnBrief: turnBriefXml,
                sideBrief: sideBriefXml,
                workspaceNotice: workspaceNoticeXml,
                dynamicReminders: formatDynamicRemindersXml([
                    ...(preRenderedDynamicReminders ?? []),
                    ...(rest.dynamicReminders ?? []),
                ]),
                loreHint: loreHintXml,
                sideHint: sideHintXml,
            };
        };

        const initialDynamicFingerprint = computePrefixDynamicFingerprint(
            prefixDeps,
            session,
            outletMacroOverrides,
            prefixDeps.autoPromptDynamicKeys.length > 0
                ? buildDynamicAutoPromptFingerprintValues()
                : undefined,
        );
        const frozenMatches = doesFrozenPrefixMatch(
            existingFrozen,
            staticPrefixFingerprint,
            initialDynamicFingerprint,
        );

        let effectiveForceRecompilePrefix =
            Boolean(rest.forceRecompilePrefix) || (Boolean(existingFrozen) && !frozenMatches);
        const initialWillUseFrozenPrefix =
            Boolean(existingFrozen) && frozenMatches && !rest.forceRecompilePrefix;

        // Step D: Phase 1 — Render blocks & inline lore with forceOutlet=true
        const newlyRenderedPrefixIds: string[] = [];
        const newlyRenderedTailIds: string[] = [];
        const newlyRenderedFloatingIds: string[] = [];
        const prefixBlockMetas = new Map<string, PromptBlockTransformMeta>();
        const floatingBlockMetas = new Map<string, PromptBlockTransformMeta>();

        let renderedRuleByKey: Record<string, string> | undefined;
        let nonCacheableSystemRuleKeys: string[] = [];
        const prefixHookCacheKeys: Record<string, string> = {};
        let selectiveFrozenHit = false;
        let selectivePrefixReevaluated = false;
        let selectiveRulesChanged = false;
        let selectivePrefixIdsToReeval = new Set<string>();

        let fullCombinedMacroOverrides: Record<string, string> = { ...combinedMacroOverrides };

        session.setForceOutlet(true);
        try {
            if (!initialWillUseFrozenPrefix) {
                if (claimed.prefix.has('systemRules') && preRenderedSystemRules === undefined) {
                    const ruleRes = await renderSystemRulesAsync();
                    preRenderedSystemRules = ruleRes.renderedRules;
                    renderedRuleByKey = ruleRes.ruleTextByKey;
                    nonCacheableSystemRuleKeys = ruleRes.nonCacheableKeys;
                    Object.assign(prefixHookCacheKeys, ruleRes.cacheKeys);
                }

                if (
                    systemBaseHandling.suppressAutoSystemBase
                    && systemBaseHandling.isActiveSystemBaseBlock
                    && systemBaseHandling.systemBaseBlock
                    && systemBaseHandling.systemBaseBlock.role !== 'custom'
                ) {
                    const baseBlock = systemBaseHandling.systemBaseBlock;
                    if (preRenderedBlocks.has(baseBlock.id)) {
                        resolvedSystemBaseText = extractRenderedMessagesText(
                            preRenderedBlocks.get(baseBlock.id) ?? [],
                        );
                    } else {
                        const baseMacroOverrides: Record<string, string> = {
                            ...combinedMacroOverrides,
                            ...buildAutoPromptMacroOverrides({
                                coreManifest: manifestText,
                                ...(preRenderedSystemRules !== undefined
                                    ? { systemRules: formatSystemRulesXml(preRenderedSystemRules) }
                                    : {}),
                            }),
                        };
                        const renderedBase = await prerenderPromptBlocks([baseBlock], {
                            hostBridge,
                            macroOverrides: baseMacroOverrides,
                            vars: liveVars,
                            injectionSession: session,
                            ejsSession,
                            transformSessionId,
                            transformAgentId: rest.agent.id,
                            transformPhase,
                            transformTarget: transformTarget,
                            transformSessionBag,
                            transformLayer: 'layer0_prefix',
                            signal: rest.signal,
                            onVariablesMutated: applyTurnVarUpdates,
                        });
                        resolvedSystemBaseText = extractRenderedMessagesText(
                            renderedBase.get(baseBlock.id) ?? [],
                        );
                    }
                }

                const prefixAutoOverrides = buildAutoPromptMacroOverrides({
                    systemBase: resolvedSystemBaseText,
                    coreManifest: manifestText,
                    ...(preRenderedSystemRules !== undefined
                        ? { systemRules: formatSystemRulesXml(preRenderedSystemRules) }
                        : {}),
                    ...(rest.inFlightMessages === undefined
                        ? {
                              turnBrief: turnBriefXml,
                              sideBrief: sideBriefXml,
                              workspaceNotice: workspaceNoticeXml,
                              loreHint: loreHintXml,
                              sideHint: sideHintXml,
                              ...(preRenderedDynamicReminders !== undefined || rest.dynamicReminders
                                  ? {
                                        dynamicReminders: formatDynamicRemindersXml([
                                            ...(preRenderedDynamicReminders ?? []),
                                            ...(rest.dynamicReminders ?? []),
                                        ]),
                                    }
                                  : {}),
                          }
                        : {}),
                });
                const prefixMacroOverrides: Record<string, string> = {
                    ...combinedMacroOverrides,
                    ...(rest.inFlightMessages !== undefined
                        ? fillMissingLayer2AutoOverrides(rest.macroOverrides)
                        : {}),
                    ...prefixAutoOverrides,
                };

                const prefixBlocksToRender = matchingPrefixBlocks.filter(
                    (block) =>
                        !preRenderedBlocks.has(block.id)
                        && !(systemBaseHandling.suppressAutoSystemBase && block.id === 'system_base'),
                );
                if (prefixBlocksToRender.length > 0) {
                    const renderedPrefix = await prerenderPromptBlocks(prefixBlocksToRender, {
                        hostBridge,
                        macroOverrides: prefixMacroOverrides,
                        vars: liveVars,
                        injectionSession: session,
                        ejsSession,
                        transformSessionId,
                        transformAgentId: rest.agent.id,
                        transformPhase,
                        transformTarget: transformTarget,
                        transformSessionBag,
                        transformLayer: 'layer0_prefix',
                        signal: rest.signal,
                        onTransformMeta: (meta) => {
                            prefixBlockMetas.set(meta.blockId, meta);
                        },
                        onVariablesMutated: applyTurnVarUpdates,
                    });
                    for (const [blockId, messages] of renderedPrefix.entries()) {
                        preRenderedBlocks.set(blockId, messages);
                        newlyRenderedPrefixIds.push(blockId);
                    }
                }

                if (preRenderedSystemRules === undefined) {
                    const ruleRes = await renderSystemRulesAsync();
                    preRenderedSystemRules = ruleRes.renderedRules;
                    renderedRuleByKey = ruleRes.ruleTextByKey;
                    if (!claimed.tail.has('systemRules')) {
                        nonCacheableSystemRuleKeys = ruleRes.nonCacheableKeys;
                        Object.assign(prefixHookCacheKeys, ruleRes.cacheKeys);
                    }
                }
            } else {
                const existingNonCacheableBlockIds = existingFrozen?.nonCacheablePrefixBlockIds ?? [];
                const existingNonCacheableRuleKeys = existingFrozen?.nonCacheableSystemRuleKeys ?? [];
                const hasSelectiveNonCacheablePrefix =
                    existingNonCacheableBlockIds.length > 0 || existingNonCacheableRuleKeys.length > 0;

                if (hasSelectiveNonCacheablePrefix && existingFrozen) {
                    selectivePrefixReevaluated = true;
                    const cachedRulesMap = existingFrozen.cachedSystemRules ?? {};
                    if (existingNonCacheableRuleKeys.length > 0 && preRenderedSystemRules === undefined) {
                        const ruleRes = await renderSystemRulesAsync({
                            onlyKeys: new Set(existingNonCacheableRuleKeys),
                            cachedByKey: cachedRulesMap,
                        });
                        preRenderedSystemRules = ruleRes.renderedRules;
                        renderedRuleByKey = ruleRes.ruleTextByKey;
                        nonCacheableSystemRuleKeys = ruleRes.nonCacheableKeys;
                        Object.assign(prefixHookCacheKeys, ruleRes.cacheKeys);
                        selectiveRulesChanged = ruleRes.changed;
                    } else if (preRenderedSystemRules === undefined && existingFrozen.cachedSystemRules) {
                        const cachedList: string[] = [];
                        renderedRuleByKey = { ...existingFrozen.cachedSystemRules };
                        for (const item of systemRuleEntries) {
                            const txt = existingFrozen.cachedSystemRules[systemRuleCacheKey(item)] ?? '';
                            if (txt) {
                                cachedList.push(txt);
                            }
                        }
                        preRenderedSystemRules = cachedList;
                    }

                    selectivePrefixIdsToReeval = new Set(existingNonCacheableBlockIds);
                    if (selectiveRulesChanged) {
                        for (const block of matchingPrefixBlocks) {
                            if (extractAutoPromptMacroKeys(block.content).has('systemRules')) {
                                selectivePrefixIdsToReeval.add(block.id);
                            }
                        }
                    }

                    const selectivePrefixOverrides: Record<string, string> = {
                        ...combinedMacroOverrides,
                        ...(rest.inFlightMessages !== undefined
                            ? fillMissingLayer2AutoOverrides(rest.macroOverrides)
                            : {}),
                        ...buildAutoPromptMacroOverrides({
                            systemBase: resolvedSystemBaseText,
                            coreManifest: manifestText,
                            ...(preRenderedSystemRules !== undefined
                                ? { systemRules: formatSystemRulesXml(preRenderedSystemRules) }
                                : {}),
                            ...(rest.inFlightMessages === undefined
                                ? {
                                      turnBrief: turnBriefXml,
                                      sideBrief: sideBriefXml,
                                      workspaceNotice: workspaceNoticeXml,
                                      loreHint: loreHintXml,
                                      sideHint: sideHintXml,
                                      ...(preRenderedDynamicReminders !== undefined || rest.dynamicReminders
                                          ? {
                                                dynamicReminders: formatDynamicRemindersXml([
                                                    ...(preRenderedDynamicReminders ?? []),
                                                    ...(rest.dynamicReminders ?? []),
                                                ]),
                                            }
                                          : {}),
                                  }
                                : {}),
                        }),
                    };

                    for (const block of matchingPrefixBlocks) {
                        if (!selectivePrefixIdsToReeval.has(block.id) && !preRenderedBlocks.has(block.id)) {
                            const cachedMsgs = existingFrozen.cachedPrefixBlocks?.[block.id];
                            if (cachedMsgs) {
                                preRenderedBlocks.set(
                                    block.id,
                                    canonicalClone(cachedMsgs) as CanonicalMessage[],
                                );
                            }
                        }
                    }

                    const prefixBlocksToReeval = matchingPrefixBlocks.filter(
                        (block) => selectivePrefixIdsToReeval.has(block.id) && !preRenderedBlocks.has(block.id),
                    );
                    if (prefixBlocksToReeval.length > 0) {
                        const renderedPrefix = await prerenderPromptBlocks(prefixBlocksToReeval, {
                            hostBridge,
                            macroOverrides: selectivePrefixOverrides,
                            vars: liveVars,
                            injectionSession: session,
                            ejsSession,
                            transformSessionId,
                            transformAgentId: rest.agent.id,
                            transformPhase,
                            transformTarget: transformTarget,
                            transformSessionBag,
                            transformLayer: 'layer0_prefix',
                            signal: rest.signal,
                            onTransformMeta: (meta) => {
                                prefixBlockMetas.set(meta.blockId, meta);
                            },
                            onVariablesMutated: applyTurnVarUpdates,
                        });
                        for (const [blockId, messages] of renderedPrefix.entries()) {
                            preRenderedBlocks.set(blockId, messages);
                            newlyRenderedPrefixIds.push(blockId);
                        }
                    }
                }

                if (rest.inFlightMessages === undefined) {
                    const sideEffectPrefixBlocks = matchingPrefixBlocks.filter(
                        (block) =>
                            !selectivePrefixIdsToReeval.has(block.id)
                            && hasPrefixSideEffect(block.content),
                    );
                    if (sideEffectPrefixBlocks.length > 0) {
                        const sideEffectMacroOverrides: Record<string, string> = {
                            ...combinedMacroOverrides,
                            ...buildAutoPromptMacroOverrides({
                                systemBase: resolvedSystemBaseText,
                                coreManifest: manifestText,
                            }),
                        };
                        await prerenderPromptBlocks(sideEffectPrefixBlocks, {
                            hostBridge,
                            macroOverrides: sideEffectMacroOverrides,
                            vars: liveVars,
                            injectionSession: session,
                            ejsSession,
                            transformSessionId,
                            transformAgentId: rest.agent.id,
                            transformPhase,
                            transformTarget: transformTarget,
                            transformSessionBag,
                            transformLayer: 'layer0_prefix',
                            signal: rest.signal,
                            onVariablesMutated: applyTurnVarUpdates,
                        });
                    }
                }
                if (claimed.tail.has('systemRules') && preRenderedSystemRules === undefined) {
                    const ruleRes = await renderSystemRulesAsync();
                    preRenderedSystemRules = ruleRes.renderedRules;
                }
                if (
                    claimed.tail.has('systemBase')
                    && systemBaseHandling.suppressAutoSystemBase
                    && systemBaseHandling.isActiveSystemBaseBlock
                    && systemBaseHandling.systemBaseBlock
                    && systemBaseHandling.systemBaseBlock.role !== 'custom'
                ) {
                    const baseBlock = systemBaseHandling.systemBaseBlock;
                    if (preRenderedBlocks.has(baseBlock.id)) {
                        resolvedSystemBaseText = extractRenderedMessagesText(
                            preRenderedBlocks.get(baseBlock.id) ?? [],
                        );
                    } else {
                        const renderedBase = await prerenderPromptBlocks([baseBlock], {
                            hostBridge,
                            macroOverrides: {
                                ...combinedMacroOverrides,
                                ...buildAutoPromptMacroOverrides({
                                    coreManifest: manifestText,
                                    ...(preRenderedSystemRules !== undefined
                                        ? { systemRules: formatSystemRulesXml(preRenderedSystemRules) }
                                        : {}),
                                }),
                            },
                            vars: liveVars,
                            injectionSession: session,
                            ejsSession,
                            transformSessionId,
                            transformAgentId: rest.agent.id,
                            transformPhase,
                            transformTarget: transformTarget,
                            transformSessionBag,
                            transformLayer: 'layer0_prefix',
                            signal: rest.signal,
                            onVariablesMutated: applyTurnVarUpdates,
                        });
                        resolvedSystemBaseText = extractRenderedMessagesText(
                            renderedBase.get(baseBlock.id) ?? [],
                        );
                    }
                }
            }

            const systemRulesXml = formatSystemRulesXml(preRenderedSystemRules ?? []);
            const floatTailBlocks = shouldFloatTailPromptBlocks(rest.promptTriggerContext);
            const layer2Vars =
                Object.keys(mutatedTurnVars).length > 0
                    ? { ...(rest.vars ?? {}), ...mutatedTurnVars }
                    : rest.vars;
            const preReminderMacroOverrides: Record<string, string> = {
                ...combinedMacroOverrides,
                ...(rest.inFlightMessages === undefined
                    ? buildAutoPromptMacroOverrides({
                          systemBase: resolvedSystemBaseText,
                          coreManifest: manifestText,
                          systemRules: systemRulesXml,
                          turnBrief: turnBriefXml,
                          sideBrief: sideBriefXml,
                          workspaceNotice: workspaceNoticeXml,
                          loreHint: loreHintXml,
                          sideHint: sideHintXml,
                      })
                    : {
                          ...fillMissingLayer2AutoOverrides(rest.macroOverrides),
                          ...buildAutoPromptMacroOverrides({
                              systemBase: resolvedSystemBaseText,
                              coreManifest: manifestText,
                              systemRules: systemRulesXml,
                          }),
                      }),
            };
            const layer2MacroOverrides = buildLayer2MacroOverrides(
                layer2Vars,
                preReminderMacroOverrides,
            );

            if (
                rest.inFlightMessages === undefined
                && rest.includeCategory4DynamicEntries !== false
                && preRenderedDynamicReminders === undefined
            ) {
                preRenderedDynamicReminders = await renderDynamicRemindersAsync(
                    liveVars,
                    layer2MacroOverrides,
                );
            }

            const remindersXml = formatDynamicRemindersXml([
                ...(preRenderedDynamicReminders ?? []),
                ...(rest.dynamicReminders ?? []),
            ]);
            const fullAutoOverrides =
                rest.inFlightMessages === undefined
                    ? buildAutoPromptMacroOverrides({
                          systemBase: resolvedSystemBaseText,
                          coreManifest: manifestText,
                          systemRules: systemRulesXml,
                          turnBrief: turnBriefXml,
                          sideBrief: sideBriefXml,
                          workspaceNotice: workspaceNoticeXml,
                          dynamicReminders: remindersXml,
                          loreHint: loreHintXml,
                          sideHint: sideHintXml,
                      })
                    : {
                          ...fillMissingLayer2AutoOverrides(rest.macroOverrides),
                          ...buildAutoPromptMacroOverrides({
                              systemBase: resolvedSystemBaseText,
                              coreManifest: manifestText,
                              systemRules: systemRulesXml,
                          }),
                      };
            fullCombinedMacroOverrides = {
                ...combinedMacroOverrides,
                ...fullAutoOverrides,
            };
            const tailRenderMacroOverrides = buildLayer2MacroOverrides(
                layer2Vars,
                fullCombinedMacroOverrides,
            );

            if (!floatTailBlocks && rest.inFlightMessages === undefined) {
                const tailBlocksToRender = promptBlocks.filter(
                    (b: PromptBlock) =>
                        b.enabled
                        && b.placement === 'tail'
                        && b.content.trim().length > 0
                        && matchesPromptTriggers(b.triggers, rest.promptTriggerContext)
                        && !preRenderedBlocks.has(b.id),
                );
                if (tailBlocksToRender.length > 0) {
                    const renderedTail = await prerenderPromptBlocks(tailBlocksToRender, {
                        hostBridge,
                        macroOverrides: tailRenderMacroOverrides,
                        vars: liveVars,
                        injectionSession: session,
                        ejsSession,
                        transformSessionId,
                        transformAgentId: rest.agent.id,
                        transformPhase,
                        transformTarget: transformTarget,
                        transformSessionBag,
                        transformLayer: 'layer2_tail',
                        signal: rest.signal,
                        onVariablesMutated: applyTurnVarUpdates,
                    });
                    for (const [blockId, messages] of renderedTail.entries()) {
                        preRenderedBlocks.set(blockId, messages);
                        newlyRenderedTailIds.push(blockId);
                    }
                }
            }

            const floatingBlocksToRender = promptBlocks.filter(
                (b: PromptBlock) =>
                    b.enabled
                    && (b.placement === 'floating_tail' || (floatTailBlocks && b.placement === 'tail'))
                    && b.content.trim().length > 0
                    && matchesPromptTriggers(b.triggers, rest.promptTriggerContext)
                    && !preRenderedBlocks.has(b.id),
            );
            if (floatingBlocksToRender.length > 0) {
                const latestLayer2Vars =
                    Object.keys(mutatedTurnVars).length > 0
                        ? { ...(rest.vars ?? {}), ...mutatedTurnVars }
                        : rest.vars;
                const latestLayer2MacroOverrides = buildLayer2MacroOverrides(
                    latestLayer2Vars,
                    fullCombinedMacroOverrides,
                );
                const renderedFloating = await prerenderPromptBlocks(floatingBlocksToRender, {
                    hostBridge,
                    macroOverrides: latestLayer2MacroOverrides,
                    vars: liveVars,
                    injectionSession: session,
                    ejsSession,
                    transformSessionId,
                    transformAgentId: rest.agent.id,
                    transformPhase,
                    transformTarget: transformTarget,
                    transformSessionBag,
                    transformLayer: 'layer2_floating',
                    signal: rest.signal,
                    onTransformMeta: (meta) => {
                        floatingBlockMetas.set(meta.blockId, meta);
                    },
                    onVariablesMutated: applyTurnVarUpdates,
                });
                for (const [blockId, messages] of renderedFloating.entries()) {
                    preRenderedBlocks.set(blockId, messages);
                    newlyRenderedFloatingIds.push(blockId);
                }
            }
        } finally {
            session.setForceOutlet(false);
        }

        // Step E: Phase 2 — Expand delayed {{outletPromptsInjected:...}} placeholders across all rendered parts
        const promptBlockById = new Map(promptBlocks.map((b) => [b.id, b]));
        for (const blockId of [...newlyRenderedPrefixIds, ...newlyRenderedTailIds, ...newlyRenderedFloatingIds]) {
            const msgs = preRenderedBlocks.get(blockId);
            if (msgs) {
                preRenderedBlocks.set(
                    blockId,
                    applyOutletsToCanonicalMessages(msgs, session, {
                        dropEmptyTextMessages: promptBlockById.get(blockId)?.role !== 'custom',
                    }),
                );
            }
        }
        if (resolvedSystemBaseText) {
            const nextSystemBase = session.applyOutlets(resolvedSystemBaseText).trim();
            if (nextSystemBase !== resolvedSystemBaseText) {
                resolvedSystemBaseText = nextSystemBase;
                fullCombinedMacroOverrides = {
                    ...fullCombinedMacroOverrides,
                    ...buildAutoPromptMacroOverrides({
                        systemBase: resolvedSystemBaseText,
                    }),
                };
            }
        }
        if (renderedRuleByKey) {
            const outletAppliedRules: string[] = [];
            for (const item of systemRuleEntries) {
                const key = systemRuleCacheKey(item);
                const rawRule = renderedRuleByKey[key] ?? '';
                const nextRule = rawRule ? session.applyOutlets(rawRule).trim() : '';
                renderedRuleByKey[key] = nextRule;
                if (nextRule) {
                    outletAppliedRules.push(nextRule);
                }
            }
            preRenderedSystemRules = outletAppliedRules;
            fullCombinedMacroOverrides = {
                ...fullCombinedMacroOverrides,
                ...buildAutoPromptMacroOverrides({
                    systemRules: formatSystemRulesXml(preRenderedSystemRules),
                }),
            };
        } else if (preRenderedSystemRules) {
            preRenderedSystemRules = preRenderedSystemRules
                .map((rule) => session.applyOutlets(rule).trim())
                .filter(Boolean);
            fullCombinedMacroOverrides = {
                ...fullCombinedMacroOverrides,
                ...buildAutoPromptMacroOverrides({
                    systemRules: formatSystemRulesXml(preRenderedSystemRules),
                }),
            };
        }
        if (preRenderedDynamicReminders) {
            preRenderedDynamicReminders = preRenderedDynamicReminders
                .map((line) => session.applyOutlets(line).trim())
                .filter(Boolean);
            if (rest.inFlightMessages === undefined) {
                fullCombinedMacroOverrides = {
                    ...fullCombinedMacroOverrides,
                    ...buildAutoPromptMacroOverrides({
                        dynamicReminders: formatDynamicRemindersXml([
                            ...preRenderedDynamicReminders,
                            ...(rest.dynamicReminders ?? []),
                        ]),
                    }),
                };
            }
        }

        if (selectivePrefixReevaluated && existingFrozen) {
            const cachedRulesMap = existingFrozen.cachedSystemRules ?? {};
            if (renderedRuleByKey) {
                for (const key of existingFrozen.nonCacheableSystemRuleKeys ?? []) {
                    if ((renderedRuleByKey[key] ?? '') !== (cachedRulesMap[key] ?? '')) {
                        selectiveRulesChanged = true;
                        break;
                    }
                }
            }
            let selectiveBlocksChanged = false;
            for (const blockId of newlyRenderedPrefixIds) {
                const nextMsgs = preRenderedBlocks.get(blockId) ?? [];
                const prevMsgs = existingFrozen.cachedPrefixBlocks?.[blockId];
                if (!prevMsgs || canonicalStringify(nextMsgs) !== canonicalStringify(prevMsgs)) {
                    selectiveBlocksChanged = true;
                    break;
                }
            }
            if (selectiveRulesChanged || selectiveBlocksChanged) {
                effectiveForceRecompilePrefix = true;
            } else {
                selectiveFrozenHit = true;
                effectiveForceRecompilePrefix = false;
            }
        }

        let cachedPrefixBlocksForStore: Record<string, CanonicalMessage[]> | undefined;
        let cachedSystemRulesForStore: Record<string, string> | undefined;
        let nonCacheablePrefixBlockIdsForStore: string[] | undefined;
        let nonCacheableSystemRuleKeysForStore: string[] | undefined;
        let prefixHookCacheKeysForStore: Record<string, string> | undefined;

        if (!initialWillUseFrozenPrefix || (selectivePrefixReevaluated && !selectiveFrozenHit)) {
            const nextCachedBlocks: Record<string, CanonicalMessage[]> = {};
            const nextNonCacheableBlocks: string[] = [];
            const prevNonCacheableBlockSet = new Set(existingFrozen?.nonCacheablePrefixBlockIds ?? []);
            const nextHookKeys: Record<string, string> = { ...prefixHookCacheKeys };

            for (const block of matchingPrefixBlocks) {
                const msgs = preRenderedBlocks.get(block.id);
                if (msgs) {
                    nextCachedBlocks[block.id] = canonicalClone(msgs) as CanonicalMessage[];
                }
                const meta = prefixBlockMetas.get(block.id);
                if (meta) {
                    if (!meta.cacheable) {
                        nextNonCacheableBlocks.push(block.id);
                    }
                    Object.assign(nextHookKeys, meta.cacheKeys);
                } else if (selectivePrefixReevaluated && prevNonCacheableBlockSet.has(block.id)) {
                    nextNonCacheableBlocks.push(block.id);
                }
            }

            cachedPrefixBlocksForStore = nextCachedBlocks;
            cachedSystemRulesForStore = renderedRuleByKey;
            nonCacheablePrefixBlockIdsForStore = nextNonCacheableBlocks;
            nonCacheableSystemRuleKeysForStore = nonCacheableSystemRuleKeys;
            prefixHookCacheKeysForStore = nextHookKeys;
        }

        const nonCacheableFloatingBlockIds = Array.from(floatingBlockMetas.values())
            .filter((meta) => !meta.cacheable)
            .map((meta) => meta.blockId);

        let effectiveUserInput = rest.userInput;
        let userInputTransformState: TrajectoryMessageTransformState | undefined;
        if (
            rest.inFlightMessages === undefined
            && rest.userInput !== undefined
            && hostBridge.transformPromptText
        ) {
            const isChatMessage =
                userInputIsChatMessage
                ?? (rest.promptTriggerContext === undefined || rest.promptTriggerContext.kind === 'main');

            let userMeta: { messageId?: number; swipeId?: number; name?: string; isUser?: boolean } = {};
            if (isChatMessage) {
                if (userMessageMeta) {
                    userMeta = {
                        messageId: userMessageMeta.messageId,
                        swipeId: userMessageMeta.swipeId,
                        name: rest.userName ?? userMessageMeta.name ?? hostBridge.getActiveIdentity().userName,
                        isUser: userMessageMeta.isUser ?? true,
                    };
                } else {
                    const chatList = hostBridge.getChat();
                    let matchedUserMsg: ChatMessageSnapshot | undefined;
                    if (
                        target
                        && target.messageId >= 0
                        && target.messageId < chatList.length
                        && chatList[target.messageId]?.isUser
                    ) {
                        matchedUserMsg = chatList[target.messageId];
                    } else {
                        const startIdx = target
                            ? Math.min(chatList.length - 1, target.messageId - 1)
                            : chatList.length - 1;
                        for (let idx = startIdx; idx >= 0; idx -= 1) {
                            const item = chatList[idx];
                            if (item && !item.isSystem) {
                                if (item.isUser) {
                                    matchedUserMsg = item;
                                }
                                break;
                            }
                        }
                    }
                    userMeta = {
                        ...(matchedUserMsg
                            ? { messageId: matchedUserMsg.id, swipeId: matchedUserMsg.swipeId }
                            : {}),
                        name:
                            rest.userName
                            ?? matchedUserMsg?.name
                            ?? hostBridge.getActiveIdentity().userName,
                        isUser: true,
                    };
                }
            }

            if (typeof rest.userInput === 'string') {
                const res = await transformTextWithTurnSync(rest.userInput, liveVars, {
                    source: 'user_input',
                    layer: 'layer2_tail',
                    role: 'user',
                    isChatMessage,
                    ...userMeta,
                });
                effectiveUserInput = res.text;
                userInputTransformState =
                    res.cacheable && Object.keys(res.cacheKeys).length === 0
                        ? {
                              cached: true,
                              ...(res.changed ? { rawContent: rest.userInput } : {}),
                              meta: {
                                  source: 'user_input',
                                  isChatMessage,
                                  ...userMeta,
                              },
                          }
                        : {
                              cached: false,
                              rawContent: rest.userInput,
                              meta: {
                                  source: 'user_input',
                                  isChatMessage,
                                  ...userMeta,
                              },
                          };
            } else if (Array.isArray(rest.userInput)) {
                const res = await transformCanonicalContent(hostBridge, rest.userInput, () => ({
                    source: 'user_input',
                    layer: 'layer2_tail',
                    role: 'user',
                    meta: {
                        sessionId: transformSessionId,
                        agentId: rest.agent.id,
                        phase: transformPhase,
                        ...(transformTarget ? { target: transformTarget } : {}),
                        isChatMessage,
                        ...userMeta,
                        vars: liveVars,
                        injectionSession: session,
                        ejsSession,
                    },
                    sessionBag: transformSessionBag,
                    signal: rest.signal,
                }));
                effectiveUserInput = res.content;
                userInputTransformState =
                    res.cacheable && Object.keys(res.cacheKeys).length === 0
                        ? {
                              cached: true,
                              ...(res.changed ? { rawContent: canonicalClone(rest.userInput) } : {}),
                              meta: {
                                  source: 'user_input',
                                  isChatMessage,
                                  ...userMeta,
                              },
                          }
                        : {
                              cached: false,
                              rawContent: canonicalClone(rest.userInput),
                              meta: {
                                  source: 'user_input',
                                  isChatMessage,
                                  ...userMeta,
                              },
                          };
            }
        }

        let effectiveRecentChatMessages = rest.recentChatMessages;
        let transformedRecentChatMessages: (CanonicalMessage | ChatMessageSnapshot)[] | undefined;
        if (
            rest.inFlightMessages === undefined
            && rest.agent.sessionMode !== 'persistent'
            && rest.recentChatMessages?.length
            && hostBridge.transformPromptText
        ) {
            const windowSize = Math.max(0, rest.agent.ephemeralWindowSize ?? 6);
            if (windowSize > 0) {
                const windowIndices = selectEphemeralWindowSnapshotIndices(
                    rest.recentChatMessages,
                    windowSize,
                );
                if (windowIndices.size > 0) {
                    const ephCache = this.getEphemeralCacheForBridge(hostBridge);
                    const nextHistory: (CanonicalMessage | ChatMessageSnapshot)[] = [];
                    for (let idx = 0; idx < rest.recentChatMessages.length; idx += 1) {
                        const item = rest.recentChatMessages[idx];
                        if (windowIndices.has(idx) && isChatMessageSnapshot(item) && !item.isSystem) {
                            const rawMes = item.mes ?? '';
                            const cacheKey = `${rest.agent.id}\0${item.id}\0${item.swipeId ?? 0}\0${hashString64Hex(rawMes)}`;
                            const cachedText = ephCache.get(cacheKey);
                            if (cachedText !== undefined) {
                                nextHistory.push({
                                    ...canonicalClone(item),
                                    mes: cachedText,
                                });
                                continue;
                            }
                            const role: PromptTransformRole = item.isUser ? 'user' : 'assistant';
                            const res = await transformTextWithTurnSync(rawMes, liveVars, {
                                source: 'chat_message',
                                layer: 'layer1_ephemeral',
                                role,
                                isChatMessage: true,
                                messageId: item.id,
                                swipeId: item.swipeId,
                                name: item.name,
                                isUser: item.isUser,
                            });
                            if (res.cacheable && Object.keys(res.cacheKeys).length === 0) {
                                if (ephCache.size >= 512) {
                                    const oldest = ephCache.keys().next().value;
                                    if (oldest !== undefined) {
                                        ephCache.delete(oldest);
                                    }
                                }
                                ephCache.set(cacheKey, res.text);
                            }
                            nextHistory.push({
                                ...canonicalClone(item),
                                mes: res.text,
                            });
                        } else {
                            nextHistory.push(canonicalClone(item));
                        }
                    }
                    effectiveRecentChatMessages = nextHistory;
                    transformedRecentChatMessages = nextHistory;
                }
            }
        }

        let overrideLayer1Messages = rest.overrideLayer1Messages;
        if (
            overrideLayer1Messages === undefined
            && rest.inFlightMessages === undefined
            && rest.agent.sessionMode === 'persistent'
            && rest.trajectoryStore
            && hostBridge.transformPromptText
        ) {
            overrideLayer1Messages = await resolveTrajectoryLayer1Messages({
                bridge: hostBridge,
                trajectoryStore: rest.trajectoryStore,
                threadId: rest.agent.id,
                sessionId: transformSessionId,
                agentId: rest.agent.id,
                phase: transformPhase,
                target: transformTarget,
                defaultIsChatMessage:
                    rest.promptTriggerContext === undefined
                    || rest.promptTriggerContext.kind === 'main',
                vars: liveVars,
                sessionBag: transformSessionBag,
                signal: rest.signal,
            });
        }

        const finalDynamicFingerprint = computePrefixDynamicFingerprint(
            prefixDeps,
            session,
            outletMacroOverrides,
            prefixDeps.autoPromptDynamicKeys.length > 0
                ? buildDynamicAutoPromptFingerprintValues()
                : undefined,
        );
        const finalPrefixFingerprint =
            finalDynamicFingerprint !== undefined
                ? `${staticPrefixFingerprint}|${finalDynamicFingerprint}`
                : staticPrefixFingerprint;

        const assembled = this.assemble({
            ...rest,
            ...(effectiveUserInput !== undefined ? { userInput: effectiveUserInput } : {}),
            ...(effectiveRecentChatMessages !== undefined
                ? { recentChatMessages: effectiveRecentChatMessages }
                : {}),
            ...(overrideLayer1Messages !== undefined ? { overrideLayer1Messages } : {}),
            vars: liveVars,
            forceRecompilePrefix: effectiveForceRecompilePrefix,
            loreEntries,
            loreHint,
            sideClues,
            sideHint,
            tailRadar: runTailRadar ? tailRadar : undefined,
            preRenderedBlocks,
            ...(preRenderedSystemRules !== undefined ? { preRenderedSystemRules } : {}),
            ...(preRenderedDynamicReminders !== undefined ? { preRenderedDynamicReminders } : {}),
            prefixFingerprint: finalPrefixFingerprint,
            ...(cachedPrefixBlocksForStore !== undefined
                ? { cachedPrefixBlocks: cachedPrefixBlocksForStore }
                : {}),
            ...(cachedSystemRulesForStore !== undefined
                ? { cachedSystemRules: cachedSystemRulesForStore }
                : {}),
            ...(nonCacheablePrefixBlockIdsForStore !== undefined
                ? { nonCacheablePrefixBlockIds: nonCacheablePrefixBlockIdsForStore }
                : {}),
            ...(nonCacheableSystemRuleKeysForStore !== undefined
                ? { nonCacheableSystemRuleKeys: nonCacheableSystemRuleKeysForStore }
                : {}),
            ...(prefixHookCacheKeysForStore !== undefined
                ? { prefixHookCacheKeys: prefixHookCacheKeysForStore }
                : {}),
            macroOverrides: fullCombinedMacroOverrides,
            hostBridge,
        });

        return {
            ...assembled,
            ...(nonCacheableFloatingBlockIds.length > 0
                ? { nonCacheableFloatingBlockIds }
                : {}),
            ...(transformedRecentChatMessages !== undefined
                ? { transformedRecentChatMessages }
                : {}),
            ...(overrideLayer1Messages !== undefined ? { overrideLayer1Messages } : {}),
            ...(userInputTransformState ? { userInputTransformState } : {}),
        };
        } finally {
            await hostBridge.notifyPromptTransformTurnEnd?.({
                version: 1,
                sessionId: transformSessionId,
                agentId: rest.agent.id,
                phase: transformPhase,
                ...(transformTarget
                    ? {
                          target: transformTarget,
                          messageId: transformTarget.messageId,
                          swipeId: transformTarget.swipeId,
                      }
                    : {}),
                vars: liveVars,
                sessionBag: transformSessionBag,
                ...(rest.signal ? { signal: rest.signal } : {}),
            });
        }
    }

    /**
     * Append a completed turn into `TrajectoryStore` (applying `ingest` regex ONCE to
     * `/output.md` tool-call payloads in `turnMessages` and `finalAssistantMessage`
     * before freezing) and record the `(messageId, swipeId)` checkpoint.
     */
    finalizeTurn(input: FinalizeTurnInput): void {
        const agentId = input.agentId ?? DEFAULT_MAIN_AGENT_ID;
        const messagesToAppend: CanonicalMessage[] = input.turnMessages.map((m) =>
            ingestTurnOutputMessage(m, input.regex),
        );
        const transformStates: Array<TrajectoryMessageTransformState | undefined> =
            input.turnMessages.map((_, idx) => input.turnTransformStates?.[idx]);

        if (input.finalAssistantMessage) {
            const ingestedFinal = ingestCanonicalMessage(input.finalAssistantMessage, input.regex);
            messagesToAppend.push(ingestedFinal);
            const finalState = input.finalAssistantTransformState;
            transformStates.push(
                finalState && !finalState.cached
                    ? {
                          ...finalState,
                          rawContent: canonicalClone(ingestedFinal.content),
                      }
                    : finalState,
            );
        }

        input.trajectoryStore.appendTurn(
            messagesToAppend,
            agentId,
            transformStates.some((s) => s !== undefined) ? transformStates : undefined,
        );
        input.trajectoryStore.recordCheckpoint(input.target, agentId);
    }

    private buildLayer2Messages(
        input: ContextAssembleInput,
        autoParts: {
            turnBriefXml: string;
            sideBriefXml: string;
            workspaceNoticeXml: string;
            remindersXml: string;
            loreHintXml: string;
            sideHintXml: string;
        },
        claimed: ClaimedAutoPromptMacros,
        effectiveMacroOverrides: Record<string, string>,
    ): CanonicalMessage[] {
        const layer2Messages: CanonicalMessage[] = [];
        const macroOverrides = buildLayer2MacroOverrides(input.vars, effectiveMacroOverrides);

        const tailBlocks = [
            claimed.all.has('turnBrief') ? '' : autoParts.turnBriefXml,
            claimed.all.has('sideBrief') ? '' : autoParts.sideBriefXml,
            claimed.all.has('workspaceNotice') ? '' : autoParts.workspaceNoticeXml,
            claimed.all.has('dynamicReminders') ? '' : autoParts.remindersXml,
            claimed.all.has('loreHint') ? '' : autoParts.loreHintXml,
            claimed.all.has('sideHint') ? '' : autoParts.sideHintXml,
        ].filter((s) => s.length > 0);
        const tailSuffix = tailBlocks.join('\n\n');

        // 2. User input (ingested ONCE on entry) + tail blocks
        if (Array.isArray(input.userInput)) {
            const ingestedParts = input.userInput.map((part) => {
                if (part.type === 'text') {
                    return {
                        ...part,
                        text: applyIngestRegexText(part.text, 'user', input.regex),
                    };
                }
                return { ...part };
            });
            if (tailSuffix) {
                ingestedParts.push({ type: 'text', text: tailSuffix });
            }
            if (ingestedParts.length > 0) {
                layer2Messages.push({
                    role: 'user',
                    content: ingestedParts,
                    ...(input.userName ? { name: input.userName } : {}),
                });
            }
        } else {
            const rawText = input.userInput ?? '';
            const ingestedUser = rawText
                ? applyIngestRegexText(rawText, 'user', input.regex)
                : '';
            const sections = [ingestedUser, tailSuffix].filter((s) => s.length > 0);
            if (sections.length > 0) {
                layer2Messages.push({
                    role: 'user',
                    content: sections.join('\n\n'),
                    ...(input.userName ? { name: input.userName } : {}),
                });
            }
        }

        // 3. Enabled `tail` PromptBlocks (supporting multi-message custom blocks & async pre-rendered EJS)
        if (!shouldFloatTailPromptBlocks(input.promptTriggerContext)) {
            layer2Messages.push(
                ...this.renderPlacementBlocks(['tail'], input, macroOverrides, layer2Messages),
            );
        }

        return layer2Messages;
    }

    private renderPlacementBlocks(
        placements: ReadonlyArray<'tail' | 'floating_tail'>,
        input: ContextAssembleInput,
        macroOverrides: Record<string, string> | undefined,
        precedingSeed: readonly CanonicalMessage[],
    ): CanonicalMessage[] {
        const blocks = (input.agent.promptBlocks ?? []).filter(
            (b: PromptBlock) =>
                b.enabled
                && placements.includes(b.placement as 'tail' | 'floating_tail')
                && b.content.trim().length > 0
                && matchesPromptTriggers(b.triggers, input.promptTriggerContext),
        );
        if (blocks.length === 0) {
            return [];
        }

        const out: CanonicalMessage[] = [];
        for (const block of blocks) {
            if (input.preRenderedBlocks?.has(block.id)) {
                for (const msg of input.preRenderedBlocks.get(block.id) ?? []) {
                    out.push(canonicalClone(msg));
                }
            } else {
                const rendered = renderPromptBlockSync(block, {
                    hostBridge: input.hostBridge,
                    macroOverrides,
                    precedingMessages: [...precedingSeed, ...out],
                });
                out.push(...rendered);
            }
        }
        return out;
    }

    private buildFloatingTailMessages(
        input: ContextAssembleInput,
        precedingMessages: readonly CanonicalMessage[],
        effectiveMacroOverrides?: Record<string, string>,
    ): CanonicalMessage[] {
        const macroOverrides = buildLayer2MacroOverrides(
            input.vars,
            effectiveMacroOverrides ?? input.macroOverrides,
        );
        const placements: ReadonlyArray<'tail' | 'floating_tail'> = shouldFloatTailPromptBlocks(
            input.promptTriggerContext,
        )
            ? ['tail', 'floating_tail']
            : ['floating_tail'];
        return this.renderPlacementBlocks(placements, input, macroOverrides, precedingMessages);
    }

    private computeCacheBreakpoints(params: {
        layer0Count: number;
        layer0EndIndex: number;
        layer1Count: number;
        layer1EndIndex: number;
        isPersistent: boolean;
        trajectoryStore?: TrajectoryStore;
        agentId: string;
    }): number[] {
        const points: number[] = [];
        const seen = new Set<number>();

        const pushPoint = (idx: number) => {
            if (idx >= 0 && !seen.has(idx)) {
                seen.add(idx);
                points.push(idx);
            }
        };

        pushPoint(params.layer0EndIndex);

        if (params.layer1Count > 0) {
            if (params.isPersistent && params.trajectoryStore) {
                for (const count of params.trajectoryStore.getTurnEndCounts(params.agentId)) {
                    const globalIdx = params.layer0Count + count - 1;
                    if (globalIdx > params.layer0EndIndex && globalIdx <= params.layer1EndIndex) {
                        pushPoint(globalIdx);
                    }
                }
            }
            if (params.layer1EndIndex > params.layer0EndIndex) {
                pushPoint(params.layer1EndIndex);
            }
        }

        return points;
    }
}

function selectEphemeralWindowSnapshotIndices(
    rawMessages: readonly (CanonicalMessage | ChatMessageSnapshot)[],
    windowSize: number,
): Set<number> {
    if (windowSize <= 0 || rawMessages.length === 0) {
        return new Set<number>();
    }
    const turns: number[][] = [];
    let currentTurn: number[] = [];
    for (let idx = 0; idx < rawMessages.length; idx += 1) {
        const item = rawMessages[idx];
        const isSys = isChatMessageSnapshot(item)
            ? Boolean(item.isSystem)
            : item.role === 'system';
        if (isSys) {
            continue;
        }
        const role = isChatMessageSnapshot(item)
            ? (item.isUser ? 'user' : 'assistant')
            : item.role;
        if (role === 'user' && currentTurn.length > 0) {
            turns.push(currentTurn);
            currentTurn = [idx];
        } else {
            currentTurn.push(idx);
        }
    }
    if (currentTurn.length > 0) {
        turns.push(currentTurn);
    }
    const selected = new Set<number>();
    for (const turn of turns.slice(-windowSize)) {
        for (const idx of turn) {
            selected.add(idx);
        }
    }
    return selected;
}

function extractUserTextForRadar(
    userInput: string | CanonicalContentPart[] | undefined,
): string {
    if (!userInput) {
        return '';
    }
    if (typeof userInput === 'string') {
        return userInput;
    }
    return userInput
        .filter((p): p is { type: 'text'; text: string } => p.type === 'text')
        .map((p) => p.text)
        .join('\n');
}

function stripTailMetadataTags(text: string): string {
    return text
        .replace(/<turn-brief>[\s\S]*?<\/turn-brief>/g, '')
        .replace(/<side-brief>[\s\S]*?<\/side-brief>/g, '')
        .replace(/<dynamic-reminders>[\s\S]*?<\/dynamic-reminders>/g, '')
        .replace(/<lore-hint>[\s\S]*?<\/lore-hint>/g, '')
        .replace(/<side-hint>[\s\S]*?<\/side-hint>/g, '')
        .trim();
}

function extractRecentTexts(messages: readonly CanonicalMessage[]): string[] {
    const texts: string[] = [];
    for (const msg of messages) {
        if (msg.role === 'user' || msg.role === 'assistant') {
            if (typeof msg.content === 'string') {
                const cleaned = stripTailMetadataTags(msg.content);
                if (cleaned) {
                    texts.push(cleaned);
                }
            } else {
                const text = stripTailMetadataTags(
                    msg.content
                        .filter((p): p is { type: 'text'; text: string } => p.type === 'text')
                        .map((p) => p.text)
                        .join('\n'),
                );
                if (text) {
                    texts.push(text);
                }
            }
        }
    }
    return texts;
}
